-- =============================================================================
-- 486 — LE CAHIER D'EXERCICES DE 4E (partie 5)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 486 --niveau 4e --fichiers francais.n1,francais.n2,histoire-geo.n1 --suffixe 5 > supabase/contenu/486_exercices_4e_5.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n1             27 exercices · 9 chapitres
--   francais.n2             27 exercices · 9 chapitres
--   histoire-geo.n1         27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un poème dans la nuit","competence":"analyser-texte","situation":"Le club poésie du collège a reçu un poème anonyme déposé dans la boîte aux lettres. Avant de le lire à voix haute, Samir veut repérer ce qui en fait un poème lyrique.","documents":[{"id":"nocturne","type":"texte","genre":"poeme","titre":"Nocturne","blocs":["Ô Lune, silencieuse amie, reste auprès de moi !","Je cache mes larmes derrière un sourire.","La peine est si lourde, et personne ne voit","Comme mon cœur souffre quand la nuit respire."],"source":"Poème écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre mots** qui renvoient au poète lui-même (la première personne).","aide":"Cherche un pronom (je, moi) et des déterminants (mon, mes).","type":"zone","document":"nocturne","multiple":true},{"enonce":"Touche l’**apostrophe** : les mots par lesquels le poète s’adresse directement à la lune.","aide":"Une apostrophe commence souvent par « Ô » et interpelle quelqu’un ou quelque chose.","type":"zone","document":"nocturne","multiple":true},{"enonce":"Touche les **trois mots** du champ lexical de la tristesse : un nom de ce qui coule des yeux, un nom de douleur et un verbe.","aide":"Cherche ce qui coule des yeux, ce qui pèse sur le cœur, ce que fait le cœur.","type":"zone","document":"nocturne","multiple":true},{"enonce":"Pourquoi ce poème est-il un poème lyrique ?","aide":"Le mot « lyrique » vient de la lyre : que chantait-on avec elle ?","type":"choix","options":[{"id":"a","texte":"Il décrit un paysage de façon neutre, sans aucune émotion"},{"id":"b","texte":"Il défend une opinion politique en s’adressant au peuple"},{"id":"c","texte":"Il raconte une longue aventure avec de nombreux personnages"},{"id":"d","texte":"Il exprime les sentiments personnels de celui qui parle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m8","m10","m25"]},"explication":"Les marques de la première personne sont **moi, Je, mes, mon** : c’est le poète qui parle de lui, ce qui est la base du lyrisme."},{"cle":{"type":"zone","ids":["m0","m1"]},"explication":"**Ô Lune** est une apostrophe : le poète parle à la lune comme à une amie."},{"cle":{"type":"zone","ids":["m11","m16","m27"]},"explication":"**larmes**, **peine** et **souffre** appartiennent au champ lexical du chagrin, très présent dans la poésie lyrique."},{"cle":{"type":"choix","ids":["d"]},"explication":"La poésie lyrique exprime **les sentiments personnels du poète** : ici sa tristesse, dite à la première personne."}]$ex$::jsonb),
  ('a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Une rose et une jeune fille","competence":"analyser-texte","situation":"Pour la soirée poésie du collège, Inès doit choisir un poème d’amour à lire. Elle hésite entre un poème de la Renaissance et trois poèmes du siècle dernier : voici l’affiche et le début du texte de Ronsard.","documents":[{"id":"ronsard","type":"texte","genre":"poeme","titre":"Mignonne, allons voir si la rose…","blocs":["Mignonne, allons voir si la rose","Qui ce matin avait déclose","Sa robe de pourpre au soleil,","A point perdu cette vesprée","Les plis de sa robe pourprée,","Et son teint au vôtre pareil."],"auteur":"Pierre de Ronsard","source":"Ronsard, Odes (1550), première strophe"},{"id":"affiche","type":"fiche","modele":"affiche","entete":"Soirée poésie d’amour","sousTitre":"Salle polyvalente — jeudi, 18 h","emoji":"🌹","teinte":"violet","lignes":[{"texte":"Ronsard","valeur":"« Mignonne, allons voir si la rose… »","id":"z1"},{"texte":"Apollinaire","valeur":"« Le Pont Mirabeau »","id":"z2"},{"texte":"Éluard","valeur":"« Liberté »","id":"z3"},{"texte":"Aragon","valeur":"« Les Yeux d’Elsa »","id":"z4"}],"pied":"Entrée libre"}],"questions":[{"enonce":"Touche le mot par lequel Ronsard s’adresse directement à celle qu’il invite à sortir.","aide":"C’est une apostrophe : un nom ou un surnom affectueux, en tête du poème.","type":"zone","document":"ronsard","multiple":true},{"enonce":"À qui Ronsard compare-t-il la fleur dont le teint a changé ?","aide":"Relis le dernier vers : « son teint au vôtre pareil ». Qui est « vous » ?","type":"choix","options":[{"id":"a","texte":"À un soleil du matin qui brûle toutes les fleurs du jardin"},{"id":"b","texte":"À un soldat qui a perdu son uniforme pendant le combat"},{"id":"c","texte":"À une robe que la jeune fille aurait déchirée la veille"},{"id":"d","texte":"À la jeune fille à qui il parle : son teint est pareil au sien"}],"multiple":false},{"enonce":"Touche les **deux mots** de la même famille qui disent la couleur de la fleur.","aide":"Cherche une couleur, d’abord sous la forme d’un nom, puis d’un adjectif.","type":"zone","document":"ronsard","multiple":true},{"enonce":"Sur l’affiche, touche les **trois poètes** qui écrivent au XXe siècle.","aide":"Ronsard fait partie de la Pléiade. Les trois autres ont renouvelé la forme du poème au XXe siècle.","type":"zone","document":"affiche","multiple":true},{"enonce":"Ronsard écrit au XVIe siècle, Aragon au XXe. Combien de siècles les séparent ?","aide":"Compte de siècle en siècle : XVIe, XVIIe…","type":"nombre","unite":"siècles"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"**Mignonne** est une apostrophe : Ronsard s’adresse directement à la jeune fille, ce qui est une marque du lyrisme."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le dernier vers compare le teint de la fleur à celui de **la jeune fille** : la fleur qui se fane annonce que sa beauté passera aussi."},{"cle":{"type":"zone","ids":["m14","m27"]},"explication":"**pourpre** et **pourprée** sont de la même famille : la fleur est d’un rouge profond, symbole d’une beauté qui ne dure pas."},{"cle":{"type":"zone","ids":["z2","z3","z4"]},"explication":"Apollinaire, Éluard et Aragon sont des poètes du **XXe siècle** ; Ronsard, lui, écrit au XVIe siècle."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 siècles","explication":"Du XVIe au XXe siècle, il y a **4 siècles** (20 − 16 = 4)."}]$ex$::jsonb),
  ('a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"De Sappho aux poètes d’aujourd’hui","competence":"se-reperer-temps","situation":"Léa prépare un exposé sur la poésie lyrique. Elle a dessiné une frise des grandes étapes du genre et recopié une plainte écrite par sa grande sœur, qu’elle voudrait classer dans la bonne forme.","documents":[{"id":"frise","type":"frise","titre":"La poésie lyrique à travers les siècles","debut":-600,"fin":2000,"pas":200,"periodes":[{"id":"z1","debut":-600,"fin":-500,"nom":"Sappho","teinte":"rose"},{"id":"z2","debut":500,"fin":1500,"nom":"Moyen Âge","teinte":"ambre"},{"id":"z3","debut":1500,"fin":1600,"nom":"La Pléiade","teinte":"vert"},{"id":"z4","debut":1800,"fin":1900,"nom":"Romantisme","teinte":"bleu"},{"id":"z5","debut":1900,"fin":2000,"nom":"XXe siècle","teinte":"turquoise"}],"evenements":[]},{"id":"plainte","type":"texte","genre":"poeme","titre":"Plainte d’hiver","blocs":["Hélas ! tu es partie, et mon cœur s’est éteint.","Je t’appelle en pleurant dans le jardin désert.","Ô toi qui ne viens plus, entends mon long chagrin !","Je me plains au silence, aux arbres, à l’hiver."],"source":"Poème écrit pour l’exercice"}],"questions":[{"enonce":"Les troubadours inventent l’amour courtois : sur la frise, touche leur période.","aide":"Les troubadours chantent bien après l’Antiquité, mais avant la Pléiade.","type":"zone","document":"frise","multiple":false},{"enonce":"Range ces poètes du plus ancien au plus récent, en t’aidant de la frise.","aide":"Sappho, la Pléiade, le romantisme, le XXe siècle : retrouve la période de chacun.","type":"ordre","items":[{"id":"a","texte":"Hugo"},{"id":"b","texte":"Sappho"},{"id":"c","texte":"Aragon"},{"id":"d","texte":"Ronsard"}]},{"enonce":"Dans la plainte de la sœur de Léa, touche l’apostrophe.","aide":"Cherche les deux mots, au début d’un vers, par lesquels le poète interpelle la personne absente.","type":"zone","document":"plainte","multiple":true},{"enonce":"Complète le classement de ce poème.","aide":"La plainte a un nom de forme ; le poème de 14 vers aussi.","type":"trous","segments":["Ce poème exprime la plainte : c’est une ",0,". Il compte 4 vers et non 14 : ce n’est donc pas un ",1,"."],"banque":["ode","sonnet","élégie","ballade"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Les troubadours vivent au **Moyen Âge** : ils inventent l’amour courtois, où le poète sert une dame inaccessible."},{"cle":{"type":"ordre","ids":["b","d","a","c"]},"explication":"Dans l’ordre : **Sappho** (VIe siècle av. J.-C.), **Ronsard** (La Pléiade, XVIe), **Hugo** (romantisme, XIXe), **Aragon** (XXe)."},{"cle":{"type":"zone","ids":["m19","m20"]},"explication":"**Ô toi** est l’apostrophe : le poète s’adresse à celle qui est partie, comme dans beaucoup de poèmes lyriques."},{"cle":{"type":"trous","trous":[["elegie","une elegie"],["sonnet","un sonnet"]]},"affichage":"élégie · sonnet","explication":"Le poème de la plainte est l’**élégie** ; le **sonnet** compte 14 vers (deux quatrains, deux tercets)."}]$ex$::jsonb),
  ('e44539ef-c1f1-509f-bb81-3f1246281327'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un voyageur part à l’aube","competence":"analyser-texte","situation":"Nina découvre un poème de Victor Hugo en cours de français. Avant de comprendre qui est « tu », elle commence par repérer le temps des verbes et les dates qui entourent le poème.","documents":[{"id":"strophe1","type":"texte","genre":"poeme","titre":"Première strophe","blocs":["Demain, dès l’aube, à l’heure où blanchit la campagne,","Je partirai. Vois-tu, je sais que tu m’attends.","J’irai par la forêt, j’irai par la montagne.","Je ne puis demeurer loin de toi plus longtemps."],"auteur":"Victor Hugo","source":"Victor Hugo, « Demain, dès l’aube… », Les Contemplations (1856)"},{"id":"frise","type":"frise","titre":"Autour du poème","debut":1840,"fin":1860,"pas":5,"periodes":[],"evenements":[{"id":"z1","date":1843,"nom":"Mort de Léopoldine"},{"id":"z2","date":1856,"nom":"Les Contemplations"}]}],"questions":[{"enonce":"Touche les **trois verbes conjugués au futur** dans cette strophe.","aide":"Le futur de « partir » et d’« aller » se termine par -rai. Il y en a trois dans la strophe.","type":"zone","document":"strophe1","multiple":true},{"enonce":"Combien d’années séparent la mort de Léopoldine de la publication des Contemplations ?","aide":"Soustrais la date de la mort de celle de la publication.","type":"nombre","unite":"ans"},{"enonce":"D’après la frise, à qui le poète dit-il « tu » ?","aide":"Qui meurt en 1843, selon la frise ? Le poème est publié en 1856 dans un recueil de souvenirs et de deuil.","type":"choix","options":[{"id":"a","texte":"À la Seine, qu’il veut remonter jusqu’à sa source"},{"id":"b","texte":"À Léopoldine, sa fille, morte noyée en 1843"},{"id":"c","texte":"À un ami d’enfance qui habite près d’Harfleur"},{"id":"d","texte":"À sa femme, restée à la maison pendant le voyage"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m12","m21","m26"]},"explication":"**partirai, irai, irai** sont au futur : le poète annonce un voyage qu’il tient pour certain."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 ans","explication":"1856 − 1843 = **13 ans** : Hugo a écrit ce poème sur son deuil, puis l’a publié treize ans après la mort de sa fille."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le « tu » est **Léopoldine**, la fille de Hugo, noyée en septembre 1843 : le poème ne la nomme jamais."}]$ex$::jsonb),
  ('e44539ef-c1f1-509f-bb81-3f1246281327'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Marcher sans rien voir","competence":"analyser-texte","situation":"Sacha et Lina relisent les deux dernières strophes de « Demain, dès l’aube… ». Ils veulent comprendre pourquoi le voyageur ne regarde rien autour de lui.","documents":[{"id":"strophes","type":"texte","genre":"poeme","titre":"Strophes 2 et 3","blocs":["Je marcherai les yeux fixés sur mes pensées,","Sans rien voir au dehors, sans entendre aucun bruit,","Seul, inconnu, le dos courbé, les mains croisées,","Triste, et le jour pour moi sera comme la nuit.","","Je ne regarderai ni l’or du soir qui tombe,","Ni les voiles au loin descendant vers Harfleur,","Et, quand j’arriverai, je mettrai sur ta tombe","Un bouquet de houx vert et de bruyère en fleur."],"auteur":"Victor Hugo","source":"Victor Hugo, « Demain, dès l’aube… », Les Contemplations (1856)"}],"questions":[{"enonce":"Touche les **deux mots** qui répètent le refus de regarder (« … ni l’or du soir… ni les voiles… »).","aide":"Une même petite conjonction de négation ouvre les deux vers.","type":"zone","document":"strophes","multiple":true},{"enonce":"Pourquoi le marcheur ne regarde-t-il ni l’or du soir ni les voiles ?","aide":"Relis le vers 1 de la strophe 2 : où sont fixés ses yeux ?","type":"choix","options":[{"id":"a","texte":"Il est pressé de rentrer chez lui avant que la nuit tombe sur la forêt"},{"id":"b","texte":"Il a perdu la vue pendant son long voyage à travers la montagne"},{"id":"c","texte":"Il craint que les bateaux ne le voient passer et ne le suivent"},{"id":"d","texte":"Rien du monde ne l’intéresse : il est tout entier tourné vers son but"}],"multiple":false},{"enonce":"Touche les **deux mots** qui disent comment il tient son dos et ses mains.","aide":"Cherche deux participes passés dans le troisième vers de la strophe 2.","type":"zone","document":"strophes","multiple":true},{"enonce":"Range chaque élément : le marcheur l’ignore, ou s’y consacre ?","aide":"Ce qu’il refuse de voir est introduit par « ni » ; ce qu’il fixe ou apporte est introduit autrement.","type":"categories","categories":[{"id":"c0","texte":"Il l’ignore"},{"id":"c1","texte":"Il s’y consacre"}],"items":[{"id":"i0","texte":"Ses pensées"},{"id":"i1","texte":"L’or du soir"},{"id":"i2","texte":"Les voiles vers Harfleur"},{"id":"i3","texte":"Un bouquet de houx et de bruyère"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38","m45"]},"explication":"Les deux **ni** forment une négation répétée : le poète refuse de regarder le monde extérieur."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il marche « les yeux fixés sur [ses] pensées » : son esprit est entièrement occupé par **son but**, qui ne se révélera qu’à la fin."},{"cle":{"type":"zone","ids":["m21","m24"]},"explication":"**courbé** et **croisées** montrent un homme voûté, accablé : ces indices ne se comprennent vraiment qu’à la relecture."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Il **ignore** le paysage (l’or du soir, les voiles) et **s’y consacre** à ses pensées, puis au bouquet qu’il déposera."}]$ex$::jsonb),
  ('e44539ef-c1f1-509f-bb81-3f1246281327'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le mot qui change tout","competence":"analyser-texte","situation":"Léo a lu le poème en entier avec un camarade qui y voit une simple promenade d’amoureux. Lis le poème, puis leur échange de messages : qui a raison, et comment le prouver ?","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Demain, dès l’aube…","blocs":["Demain, dès l’aube, à l’heure où blanchit la campagne,","Je partirai. Vois-tu, je sais que tu m’attends.","J’irai par la forêt, j’irai par la montagne.","Je ne puis demeurer loin de toi plus longtemps.","","Je marcherai les yeux fixés sur mes pensées,","Sans rien voir au dehors, sans entendre aucun bruit,","Seul, inconnu, le dos courbé, les mains croisées,","Triste, et le jour pour moi sera comme la nuit.","","Je ne regarderai ni l’or du soir qui tombe,","Ni les voiles au loin descendant vers Harfleur,","Et, quand j’arriverai, je mettrai sur ta tombe","Un bouquet de houx vert et de bruyère en fleur."],"auteur":"Victor Hugo","source":"Victor Hugo, « Demain, dès l’aube… », Les Contemplations (1856)"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages de Théo et d’Inès","participants":[{"nom":"Théo","emoji":"👦","cote":"droite"},{"nom":"Inès","emoji":"👧","cote":"gauche"}],"repliques":[{"qui":"Théo","texte":"J’ai lu « Demain, dès l’aube… ». C’est un amoureux qui va retrouver sa fiancée, non ?"},{"qui":"Inès","texte":"Relis le deuxième quatrain : « le dos courbé », « triste ». Il a l’air heureux, toi ?"},{"qui":"Théo","texte":"Il est un peu fatigué, c’est tout. Il fait un long voyage."},{"qui":"Inès","texte":"Et regarde bien où il dépose le bouquet…"}]}],"questions":[{"enonce":"Dans l’avant-dernier vers, un mot révèle enfin le but du voyage. Touche-le.","aide":"Quel mot désigne l’endroit où l’on dépose un bouquet pour un mort ?","type":"zone","document":"poeme","multiple":true},{"enonce":"Compte les syllabes du vers : « Je ne puis demeurer loin de toi plus longtemps. »","aide":"Découpe ainsi : Je-ne-puis-de-meu-rer… Le « e » de « ne » et de « de » se prononce ici.","type":"nombre","unite":"syllabes"},{"enonce":"Quel élément du poème contredit l’idée de Théo (un amoureux qui va retrouver sa fiancée) ?","aide":"Cherche ce qui change le sens du bouquet, et les indices de tristesse déjà posés dans la strophe 2.","type":"choix","options":[{"id":"a","texte":"La présence du mot « bouquet », qui est un cadeau pour une fiancée"},{"id":"b","texte":"Le fait que le poète parte tôt le matin, dès l’aube, pour un long voyage"},{"id":"c","texte":"Le mot « tombe » et le refus de regarder le monde, qui disent le deuil"},{"id":"d","texte":"Le choix de la forêt et de la montagne, qui sont des lieux difficiles"}],"multiple":false},{"enonce":"Relie chaque procédé au passage qui l’illustre.","aide":"Un procédé = un effet : le futur de la certitude, le refus répété, la reprise du « je », deux plantes opposées.","type":"association","gauche":[{"id":"g0","texte":"Le futur"},{"id":"g1","texte":"La négation répétée"},{"id":"g2","texte":"L’anaphore du « je »"},{"id":"g3","texte":"L’antithèse finale"}],"droite":[{"id":"d0","texte":"« ni l’or du soir… Ni les voiles… »"},{"id":"d1","texte":"« Je partirai », « J’irai »"},{"id":"d2","texte":"Le houx vert et la bruyère en fleur"},{"id":"d3","texte":"« Je » repris en tête de phrase"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m100"]},"explication":"Le mot **tombe** renverse le sens du poème : on croyait lire un poème d’amour, c’est un poème de deuil."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 syllabes","explication":"Je-ne-puis-de-meu-rer-loin-de-toi-plus-long-temps : **12 syllabes**, c’est un alexandrin, comme tous les vers du poème."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les yeux baissés, le dos courbé et surtout la **tombe** prouvent qu’il s’agit d’un deuil : Inès a raison."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Le **futur** rend le voyage certain, la **négation** exprime le refus du monde, l’**anaphore** concentre le poème sur un geste, l’**antithèse** réunit fidélité (houx) et fragilité (bruyère)."}]$ex$::jsonb),
  ('77d56b69-676a-5c71-93dc-e13260eee0ca'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quelle pièce respecte les règles ?","competence":"lire-tableau","situation":"La mairie reçoit quatre propositions de pièces pour le festival de théâtre de la ville. L’organisatrice cherche celle qui suit les règles de la tragédie classique ; voici son tableau de synthèse (titres inventés pour l’exercice).","documents":[{"id":"programme","type":"tableau","titre":"Les quatre propositions","colonnes":["Pièce","Lieux de l’action","Durée de l’action","Sang versé sur scène"],"lignes":[["Le Roi d’Argos","Une salle du palais","Une journée","Non"],["Le Prince errant","Cinq pays différents","Trois ans","Oui"],["La Reine de Tyr","Le palais et le port","Vingt-quatre heures","Non"],["Le Duel de minuit","Une ville, puis une forêt","Deux jours","Oui"]],"enteteLignes":false,"source":"Pièces imaginées pour l’exercice"}],"questions":[{"enonce":"Touche les **deux cases** qui respectent l’unité de temps (toute l’action tient en une journée).","aide":"La règle d’unité de temps limite l’action à vingt-quatre heures.","type":"zone","document":"programme","multiple":true},{"enonce":"Touche le titre de la **seule pièce** qui respecte à la fois l’unité de lieu, l’unité de temps et la bienséance.","aide":"Cherche un seul lieu, une journée, et pas de sang sur scène.","type":"zone","document":"programme","multiple":false},{"enonce":"Quelle règle de la tragédie classique « Le Duel de minuit » rompt-il avec la mention « Oui » dans la dernière colonne ?","aide":"Que fait-on, dans la tragédie classique, des morts et de la violence ?","type":"choix","options":[{"id":"a","texte":"La règle des rangs : seuls des rois peuvent être les héros"},{"id":"b","texte":"L’unité d’action : une seule intrigue du début à la fin"},{"id":"c","texte":"La bienséance : on ne montre ni sang ni violence sur scène"},{"id":"d","texte":"L’alexandrin : chaque vers doit compter douze syllabes"}],"multiple":false}]}$ex$::jsonb,
