  ('77d56b69-676a-5c71-93dc-e13260eee0ca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Raconter la mort, ne pas la montrer","competence":"analyser-document","situation":"Une troupe répète une tragédie dans le goût du XVIIe siècle. Le metteur en scène hésite entre deux versions de la même scène (écrites pour l’exercice) : l’une respecte les règles classiques, l’autre non.","documents":[{"id":"versionA","type":"texte","genre":"theatre","titre":"Version A","blocs":[{"didascalie":"Une salle du palais. La reine attend, inquiète. Un messager entre."},{"personnage":"La Reine","replique":"Parle. Qu’est-il advenu du roi, mon époux ?"},{"personnage":"Le Messager","replique":"Madame, au fort du combat, le roi a reçu le coup fatal et il est tombé sans un mot."}],"source":"Texte écrit pour l’exercice"},{"id":"versionB","type":"texte","genre":"theatre","titre":"Version B","blocs":[{"didascalie":"Une salle du palais. Le roi et son rival se battent devant le public."},{"didascalie":"Le rival plante son épée dans la poitrine du roi, qui s’effondre en sang sur la scène."},{"personnage":"La Reine","replique":"Ah ! mon époux !"}],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Laquelle de ces deux versions respecte la bienséance de la tragédie classique ?","aide":"Dans la tragédie classique, on ne montre ni sang ni violence.","type":"choix","options":[{"id":"a","texte":"Les deux versions, car la mort y est une action grande"},{"id":"b","texte":"La version B, où la mort est jouée devant le public"},{"id":"c","texte":"Aucune des deux, car la reine devrait mourir aussi"},{"id":"d","texte":"La version A, où la mort est racontée par un messager"}],"multiple":false},{"enonce":"Dans la version A, touche la réplique qui raconte la mort du roi.","aide":"C’est la réplique du messager.","type":"zone","document":"versionA","multiple":true},{"enonce":"Dans la version B, touche la didascalie qui montre ce que la bienséance interdit.","aide":"Cherche la phrase qui décrit un geste violent et du sang, sur la scène même.","type":"zone","document":"versionB","multiple":true},{"enonce":"Range chaque choix de mise en scène.","aide":"Relis les règles : un seul lieu, personnages élevés, violence racontée.","type":"categories","categories":[{"id":"c0","texte":"Respecte la tragédie classique"},{"id":"c1","texte":"Rompt avec la tragédie classique"}],"items":[{"id":"i0","texte":"L’action se passe dans un seul palais"},{"id":"i1","texte":"Le héros est un valet qui plaisante"},{"id":"i2","texte":"Un récit raconte le duel"},{"id":"i3","texte":"L’action voyage de ville en ville"},{"id":"i4","texte":"Le héros est un roi ou un prince"},{"id":"i5","texte":"Un duel se déroule sous les yeux du public"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"La version A respecte la **bienséance** : un messager **raconte** la mort au lieu de la montrer."},{"cle":{"type":"zone","ids":["m19","m20","m21","m22","m23","m24","m25","m26","m27","m28","m29","m30","m31","m32","m33","m34","m35","m36","m37"]},"explication":"Le **récit du messager** apprend la mort au public sans la lui montrer : c’est le procédé du théâtre classique."},{"cle":{"type":"zone","ids":["m14","m15","m16","m17","m18","m19","m20","m21","m22","m23","m24","m25","m26","m27","m28","m29","m30","m31"]},"explication":"La didascalie qui décrit le coup d’épée et le sang montre ce que la **bienséance** interdit."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"La tragédie classique **raconte** la violence, tient en **un seul lieu**, et met en scène des **personnages élevés** ; le reste appartient à d’autres genres."}]$ex$::jsonb),
