   $ex${"titre":"Titus, Bérénice et Antiochus","competence":"analyser-document","situation":"En classe, vous étudiez Bérénice (1670). Le professeur vous donne un schéma des personnages, un extrait de Racine et sa préface : comment cette pièce peut-elle être une tragédie sans aucun mort ?","documents":[{"id":"schema","type":"schema","titre":"Les personnages et la loi de Rome","largeur":320,"hauteur":290,"elements":[{"forme":"rect","x":50,"y":12,"l":220,"h":40,"arrondi":8,"texte":"Les lois de Rome","teinte":"ambre","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":10,"y":110,"l":120,"h":44,"arrondi":8,"texte":"Titus","teinte":"violet","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":190,"y":110,"l":120,"h":44,"arrondi":8,"texte":"Bérénice","teinte":"rose","motif":"clair","id":"z3","zone":true},{"forme":"rect","x":100,"y":224,"l":120,"h":44,"arrondi":8,"texte":"Antiochus","teinte":"bleu","motif":"clair","id":"z4","zone":true},{"forme":"ligne","de":[70,52],"a":[70,108],"fleche":"fin","teinte":"ambre"},{"forme":"texte","x":82,"y":86,"texte":"interdisent","taille":"petit","ancre":"debut"},{"forme":"ligne","de":[132,132],"a":[188,132],"fleche":"deux","teinte":"violet"},{"forme":"texte","x":160,"y":122,"texte":"s’aiment","taille":"petit","ancre":"milieu"},{"forme":"ligne","de":[190,224],"a":[250,156],"fleche":"fin","teinte":"bleu","style":"pointilles"},{"forme":"texte","x":252,"y":196,"texte":"l’aime en silence","taille":"petit","ancre":"debut"}]},{"id":"vers","type":"texte","genre":"poeme","titre":"Bérénice, acte IV, scène 5","blocs":["Pour jamais ! Ah ! seigneur, songez-vous en vous-même","Combien ce mot cruel est affreux quand on aime ?"],"auteur":"Jean Racine","source":"Racine, Bérénice (1670), acte IV, scène 5 (Bérénice)"},{"id":"preface","type":"texte","genre":"source","titre":"Extraits de la préface","blocs":["« Ce n’est point une nécessité qu’il y ait du sang et des morts dans une tragédie » … « il suffit que l’action en soit grande »"],"auteur":"Jean Racine","source":"Racine, préface de Bérénice (extraits)"}],"questions":[{"enonce":"Sur le schéma, touche le personnage qui aime Bérénice sans le lui dire.","aide":"Cherche la flèche en pointillés.","type":"zone","document":"schema","multiple":false},{"enonce":"À la lumière de la préface, pourquoi Bérénice est-elle une tragédie bien que personne n’y meure ?","aide":"La préface dit qu’il suffit d’une « action grande ». Quelle est la grandeur de l’action ici ?","type":"choix","options":[{"id":"a","texte":"Parce que l’action est grande : l’amour s’y heurte à la loi de Rome"},{"id":"b","texte":"Parce que la reine finit par se tuer en coulisses, hors de la scène"},{"id":"c","texte":"Parce qu’Antiochus meurt de chagrin dans la dernière scène"},{"id":"d","texte":"Parce que la pièce est écrite en prose et dure plus d’une journée"}],"multiple":false},{"enonce":"Touche ce qui empêche Titus d’épouser Bérénice.","aide":"Bérénice est une reine étrangère : qui l’interdit à l’empereur ?","type":"zone","document":"schema","multiple":false},{"enonce":"Dans l’extrait, touche les **deux adjectifs** par lesquels Bérénice qualifie le mot « jamais ».","aide":"Cherche deux adjectifs qui s’accordent avec « mot », dans le second vers.","type":"zone","document":"vers","multiple":true},{"enonce":"Remets l’intrigue de la pièce dans l’ordre.","aide":"Pars de ce qui est vrai au début, puis de l’obstacle, puis des trois renoncements.","type":"ordre","items":[{"id":"a","texte":"Titus renonce à Bérénice"},{"id":"b","texte":"Antiochus reste seul"},{"id":"c","texte":"Rome lui interdit d’épouser une reine étrangère"},{"id":"d","texte":"Bérénice part"},{"id":"e","texte":"Titus, devenu empereur, aime toujours Bérénice"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**Antiochus**, roi de Comagène et ami de Titus, aime Bérénice en silence."},{"cle":{"type":"choix","ids":["a"]},"explication":"La pièce est tragique par la **grandeur de son action** et son issue sans issue heureuse : un triple renoncement, sans aucune mort."},{"cle":{"type":"zone","ids":["z1"]},"explication":"**Les lois de Rome** interdisent à l’empereur d’épouser une reine étrangère : l’amour s’oppose au devoir."},{"cle":{"type":"zone","ids":["m10","m12"]},"explication":"**cruel** et **affreux** disent la violence de la séparation : l’émotion naît des mots, pas du sang."},{"cle":{"type":"ordre","ids":["e","c","a","d","b"]},"explication":"Titus aime Bérénice, Rome l’interdit, **Titus renonce**, **Bérénice part**, **Antiochus reste seul** : c’est le triple renoncement."}]$ex$::jsonb),
  ('35a5afc0-a4ac-5dd2-b136-d64c98aaaf75'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre scènes, quatre façons de rire","competence":"analyser-document","situation":"Le club théâtre du collège prépare une comédie. Avant de répéter, la metteuse en scène affiche sur la porte le résumé de quatre scènes : chacune fait rire d’une manière différente.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"La Fausse Lettre","sousTitre":"Comédie en un acte — résumé des scènes","emoji":"🎭","teinte":"ambre","lignes":[{"texte":"Scène 1","valeur":"Le valet trébuche et renverse tout le plateau","id":"z1"},{"texte":"Scène 2","valeur":"Le maître prend son valet pour le notaire","id":"z2"},{"texte":"Scène 3","valeur":"Le vieux Géronte compte son or, même en rêve","id":"z3"},{"texte":"Scène 4","valeur":"Un jeu de mots sur « vers » et « verre »","id":"z4"}],"pied":"Comédie imaginée pour l’exercice"}],"questions":[{"enonce":"Touche la scène qui repose sur un **quiproquo** (on prend quelqu’un pour un autre).","aide":"Cherche une scène où un personnage est pris pour quelqu’un qu’il n’est pas.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la scène de **comique de caractère** (un défaut poussé jusqu’au ridicule).","aide":"Quel personnage est ridicule à cause d’un défaut qui l’obsède ?","type":"zone","document":"affiche","multiple":false},{"enonce":"Relie chaque scène à son type de comique.","aide":"Gestes, mots, situation, caractère : demande-toi ce qui fait rire dans chaque scène.","type":"association","gauche":[{"id":"g0","texte":"Le valet trébuche"},{"id":"g1","texte":"Le jeu de mots sur « vers » et « verre »"},{"id":"g2","texte":"Le notaire pris pour le valet"},{"id":"g3","texte":"Géronte compte son or en rêve"}],"droite":[{"id":"d0","texte":"Comique de mots"},{"id":"d1","texte":"Comique de gestes"},{"id":"d2","texte":"Comique de situation"},{"id":"d3","texte":"Comique de caractère"}]}]}$ex$::jsonb,
