  ('35a5afc0-a4ac-5dd2-b136-d64c98aaaf75'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Figaro répond à son maître","competence":"analyser-texte","situation":"Au XVIIIe siècle, un valet de théâtre ose parler à son maître comme à un égal. Voici la célèbre tirade de Figaro et une petite frise pour la situer dans le temps.","documents":[{"id":"tirade","type":"texte","genre":"theatre","titre":"Figaro à son maître","blocs":[{"personnage":"Figaro","replique":"Noblesse, fortune, un rang, des places, tout cela rend si fier ! Qu’avez-vous fait pour tant de biens ? Vous vous êtes donné la peine de naître, et rien de plus."}],"auteur":"Beaumarchais","source":"Beaumarchais, Le Mariage de Figaro (1784), acte V, scène 3 (extrait)"},{"id":"frise","type":"frise","titre":"Marivaux et Beaumarchais","debut":1680,"fin":1790,"pas":10,"periodes":[{"id":"z1","debut":1688,"fin":1763,"nom":"Vie de Marivaux","teinte":"violet"}],"evenements":[{"id":"z2","date":1775,"nom":"Le Barbier de Séville"},{"id":"z3","date":1784,"nom":"Le Mariage de Figaro"}]}],"questions":[{"enonce":"Touche les **quatre mots** qui énumèrent ce que le maître possède grâce à sa naissance.","aide":"Figaro énumère au début : un titre, de l’argent, une position, des charges.","type":"zone","document":"tirade","multiple":true},{"enonce":"Touche les **deux mots** qui disent le seul effort du maître pour mériter tous ces biens.","aide":"Cherche, à la fin de la tirade, ce que le maître s’est « donné ».","type":"zone","document":"tirade","multiple":true},{"enonce":"Quelle critique de la société cette tirade exprime-t-elle ?","aide":"Que reproche Figaro à celui qui a tout reçu sans rien faire ?","type":"choix","options":[{"id":"a","texte":"Les privilèges de la naissance valent moins que le mérite"},{"id":"b","texte":"Le mariage devrait toujours être arrangé par les parents"},{"id":"c","texte":"Les valets sont plus nombreux que les nobles et doivent gouverner"},{"id":"d","texte":"Les maîtres devraient augmenter les gages de leurs domestiques"}],"multiple":false},{"enonce":"Sur la frise, touche la pièce dont est tirée la tirade.","aide":"Le titre de la pièce est écrit juste au-dessus de la tirade.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent Le Barbier de Séville du Mariage de Figaro ?","aide":"Soustrais la date de la première pièce de celle de la seconde.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1","m3","m5"]},"explication":"**Noblesse, fortune, rang, places** : l’énumération montre tout ce que le maître doit à sa naissance et non à son mérite."},{"cle":{"type":"zone","ids":["m23","m25"]},"explication":"**peine** et **naître** : le maître s’est seulement « donné la peine de naître ». L’ironie de Figaro est cruelle."},{"cle":{"type":"choix","ids":["a"]},"explication":"Figaro dénonce l’**inégalité des conditions** : la naissance donne tout au maître, alors que le valet doit se faire valoir par son esprit."},{"cle":{"type":"zone","ids":["z3"]},"explication":"La tirade est tirée du **Mariage de Figaro** (1784)."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 ans","explication":"1784 − 1775 = **9 ans** entre Le Barbier de Séville (1775) et Le Mariage de Figaro (1784)."}]$ex$::jsonb),
  ('35a5afc0-a4ac-5dd2-b136-d64c98aaaf75'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un jardin, deux amoureux qui se cachent","competence":"analyser-texte","situation":"Voici une scène écrite dans l’esprit de Marivaux : deux jeunes gens qui s’aiment font tout pour ne pas se l’avouer. Le professeur y joint un dossier qui compare trois comédies du XVIIIe siècle.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Dans le jardin","blocs":[{"didascalie":"Un jardin. Lucile lit sur un banc. Damis entre, l’air de passer par hasard."},{"personnage":"Damis","replique":"Je passais, madame ; je ne vous cherchais pas."},{"personnage":"Lucile","replique":"Je l’espère, monsieur : je ne vous attendais pas non plus."},{"personnage":"Damis","replique":"Nous voilà donc d’accord sur tout, puisque nous n’avons rien à nous dire."},{"personnage":"Lucile","replique":"Rien du tout. Restez pourtant : ce banc est le mieux placé du jardin, et il est vide."},{"personnage":"Damis","replique":"Il serait cruel de laisser un banc vide. Je reste… pour lui."}],"source":"Scène écrite pour l’exercice, à la manière de Marivaux"},{"id":"dossier","type":"tableau","titre":"Trois comédies du XVIIIe siècle","colonnes":["Pièce","Auteur","Création","Obstacle à l’amour"],"lignes":[["Le Jeu de l’amour et du hasard","Marivaux","1730","L’amour-propre des personnages"],["Le Mariage de Figaro","Beaumarchais","1784","Le pouvoir du maître"],["Le Barbier de Séville","Beaumarchais","1775","Le pouvoir du tuteur"]],"enteteLignes":false}],"questions":[{"enonce":"Touche la réplique de Lucile qui trahit qu’elle veut retenir Damis.","aide":"Cherche la réplique où Lucile dit « Rien du tout » mais l’invite à rester.","type":"zone","document":"scene","multiple":true},{"enonce":"Pourquoi Lucile et Damis ne se disent-ils pas franchement qu’ils s’aiment ?","aide":"Chez Marivaux, l’obstacle n’est ni le père ni la société : il est dans les personnages eux-mêmes.","type":"choix","options":[{"id":"a","texte":"Ils sont de deux conditions trop différentes pour s’aimer"},{"id":"b","texte":"Leurs pères leur ont interdit de se parler dans le jardin"},{"id":"c","texte":"Un rival les surveille derrière le banc et les menace"},{"id":"d","texte":"Leur amour-propre les empêche de reconnaître leur sentiment"}],"multiple":false},{"enonce":"Dans le dossier, touche la case qui donne le même obstacle à l’amour que dans la scène.","aide":"Compare avec ta réponse précédente : l’obstacle est dans le cœur des personnages.","type":"zone","document":"dossier","multiple":false},{"enonce":"Range chaque trait : s’agit-il de Marivaux ou de Beaumarchais ?","aide":"Marivaux fait de l’amour un jeu de langage ; Beaumarchais critique la société.","type":"categories","categories":[{"id":"c0","texte":"Marivaux"},{"id":"c1","texte":"Beaumarchais"}],"items":[{"id":"i0","texte":"Pièce d’abord interdite par Louis XVI"},{"id":"i1","texte":"Le valet attaque les privilèges de son maître"},{"id":"i2","texte":"On parle pour ne pas s’avouer ce que l’on ressent"},{"id":"i3","texte":"Critique du pouvoir des pères et des maîtres"},{"id":"i4","texte":"L’obstacle est l’amour-propre"},{"id":"i5","texte":"Dialogue léger où chacun avance masqué"}]},{"enonce":"Complète la définition du marivaudage.","aide":"Le spectateur a un coup d’avance sur les personnages.","type":"trous","segments":["Chez Marivaux, les personnages parlent pour ne pas ",0," ce qu’ils ressentent, et le spectateur ",1," avant eux."],"banque":["comprend","s’avouer","ignore","oublier"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m49","m50","m51","m52","m53","m54","m55","m56","m57","m58","m59","m60","m61","m62","m63","m64","m65"]},"explication":"Lucile dit « rien du tout » puis demande à Damis de **rester** : elle parle pour ne pas avouer ce qu’elle ressent. C’est le marivaudage."},{"cle":{"type":"choix","ids":["d"]},"explication":"Chez Marivaux, c’est l’**amour-propre** qui fait obstacle : chacun refuse d’avouer le premier et avance masqué."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"La case **« L’amour-propre des personnages »** correspond à la scène : c’est la marque du Jeu de l’amour et du hasard."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Marivaux met en scène un **jeu de langage** et l’amour-propre ; Beaumarchais pousse la **critique sociale** si loin que Louis XVI interdit d’abord sa pièce."},{"cle":{"type":"trous","trous":[["s avouer","savouer"],["comprend"]]},"affichage":"s’avouer · comprend","explication":"Les personnages parlent pour ne pas **s’avouer** leurs sentiments, et le spectateur **comprend** avant eux."}]$ex$::jsonb),
  ('dcbb94fb-6cd1-5461-b9ca-a4fb206add7d'::uuid, 1, 1, 5, 20, 3,
