  ('dcbb94fb-6cd1-5461-b9ca-a4fb206add7d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Dorante cède, Silvia prolonge","competence":"analyser-document","situation":"Voici la scène la plus importante de l’intrigue, réécrite pour l’exercice : Dorante dit la vérité, mais Silvia ne la dit pas encore. Un schéma résume l’enchaînement des événements.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"L’aveu","blocs":[{"didascalie":"Dorante a quitté son habit de valet."},{"personnage":"Dorante","replique":"Je ne suis pas un valet : je suis Dorante. Je vous aimais sous cet habit, et je vous aimerais encore sans lui."},{"personnage":"Silvia, à part","replique":"Il parle le premier. Mais je ne dirai pas qui je suis : je veux être aimée pour moi-même."},{"personnage":"Silvia","replique":"Monsieur, je suis flattée, mais je ne suis qu’une servante."},{"personnage":"Dorante","replique":"Que m’importe ? Je vous épouserai quand même."}],"source":"Scène écrite pour l’exercice, à la manière de Marivaux"},{"id":"chaine","type":"chaine","disposition":"colonne","titre":"L’enchaînement de la pièce","noeuds":[{"id":"z1","texte":"Silvia et Dorante s’aiment sous leur déguisement"},{"id":"z2","texte":"Dorante révèle son identité, par amour"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Silvia ôte à son tour le masque"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Que faut-il écrire à la place du « ? » dans le schéma ?","aide":"Relis l’aparté de Silvia : que veut-elle encore vérifier ?","type":"choix","options":[{"id":"a","texte":"Arlequin et Lisette se disputent devant leurs maîtres"},{"id":"b","texte":"Silvia prolonge l’épreuve pour être aimée pour elle-même"},{"id":"c","texte":"Monsieur Orgon interdit le mariage de sa fille à Dorante"},{"id":"d","texte":"Dorante découvre que Silvia est en réalité une servante"}],"multiple":false},{"enonce":"Touche la réplique qui explique pourquoi Silvia ne se dévoile pas encore.","aide":"C’est un aparté de Silvia.","type":"zone","document":"scene","multiple":true},{"enonce":"Complète la conclusion sur la fin de la pièce.","aide":"La pièce célèbre le sentiment, mais ne bouleverse pas la société.","type":"trous","segments":["À la fin, l’ordre social n’est pas ",0," : maîtres et valets se marient chacun dans leur ",1,"."],"banque":["oublié","pays","condition","renversé"]},{"enonce":"Relie chaque personnage à son rôle dans le dénouement.","aide":"Pense au double registre : qui est dans la confidence ?","type":"association","gauche":[{"id":"g0","texte":"Dorante"},{"id":"g1","texte":"Silvia"},{"id":"g2","texte":"Monsieur Orgon et Mario"},{"id":"g3","texte":"Lisette et Arlequin"}],"droite":[{"id":"d0","texte":"Ils se plaisent aussi, sous leur déguisement"},{"id":"d1","texte":"Il cède le premier et révèle son identité par amour"},{"id":"d2","texte":"Ils sont dans la confidence et laissent faire"},{"id":"d3","texte":"Elle prolonge l’épreuve pour être aimée pour elle-même"}]}]}$ex$::jsonb,
