   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Don Gomès**, père de Chimène, gifle Don Diègue. Don Diègue, trop vieux pour se venger, demande à son fils Rodrigue de le faire."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Chimène** doit réclamer au roi la mort de Rodrigue, qui a tué son père Don Gomès : elle aime pourtant Rodrigue."},{"cle":{"type":"ordre","ids":["a","f","b","d","c","e"]},"explication":"L’**affront** lance le choix de Rodrigue, puis le duel, la demande de Chimène, la victoire sur les Maures et enfin le **délai d’un an** accordé par le roi."}]$ex$::jsonb),
  ('92914028-1f3d-5b10-9383-a7c16ea1d813'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Venger un père, perdre une maîtresse","competence":"analyser-texte","situation":"Rodrigue vient d’apprendre que son père a été giflé. Seul sur scène, il dit son déchirement. Voici quatre vers de ses stances et un tableau qui résume ses deux chemins.","documents":[{"id":"stances","type":"texte","genre":"poeme","titre":"Les stances de Rodrigue","blocs":["Que je sens de rudes combats !","Contre mon propre honneur mon amour s’intéresse :","Il faut venger un père, et perdre une maîtresse.","L’un m’anime le cœur, l’autre retient mon bras."],"auteur":"Pierre Corneille","source":"Corneille, Le Cid (1637), acte I, scène 6 (extrait)"},{"id":"voies","type":"tableau","titre":"Les deux chemins de Rodrigue","colonnes":["Rodrigue choisit de…","Il garde","Il perd"],"lignes":[["Venger son père","Son honneur","?"],["Renoncer à venger son père","?","Sa valeur et son nom"]],"enteteLignes":false}],"questions":[{"enonce":"Touche les **deux verbes** qui disent entre quoi Rodrigue est déchiré.","aide":"Cherche le vers qui commence par « Il faut ».","type":"zone","document":"stances","multiple":true},{"enonce":"Compte les syllabes du dernier vers : « L’un m’anime le cœur, l’autre retient mon bras. »","aide":"Le « e » muet compte devant une consonne : ani-me le, au-tre re-tient.","type":"nombre","unite":"syllabes"},{"enonce":"D’après le tableau, que perd Rodrigue s’il venge son père ?","aide":"Qui est le père de la personne qu’il aime, et que devient-il dans le duel ?","type":"choix","options":[{"id":"a","texte":"Son père, qui meurt de chagrin"},{"id":"b","texte":"Chimène, la femme qu’il aime"},{"id":"c","texte":"Sa liberté, car le roi l’emprisonne"},{"id":"d","texte":"Son courage, perdu dans le duel"}],"multiple":false},{"enonce":"Relie chaque mot du cours à sa définition.","aide":"Les stances sont un monologue ; la tragi-comédie finit bien.","type":"association","gauche":[{"id":"g0","texte":"La tragi-comédie"},{"id":"g1","texte":"Les stances"},{"id":"g2","texte":"Le dilemme cornélien"}],"droite":[{"id":"d0","texte":"Un choix entre deux valeurs également hautes"},{"id":"d1","texte":"Le monologue où Rodrigue se déchire"},{"id":"d2","texte":"La gravité d’une tragédie, mais une fin heureuse"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m20"]},"explication":"**venger** (son père) et **perdre** (sa maîtresse) : voilà les deux termes du dilemme."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 syllabes","explication":"L’un-m’a-ni-me-le-cœur-l’au-tre-re-tient-mon-bras : **12 syllabes**, un alexandrin."},{"cle":{"type":"choix","ids":["b"]},"explication":"En vengeant son père, Rodrigue tue Don Gomès et **perd Chimène**. Quel que soit son choix, il perd quelque chose d’essentiel : c’est un dilemme."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le Cid est une **tragi-comédie** ; les **stances** sont le monologue de Rodrigue ; le **dilemme cornélien** oppose deux valeurs également hautes."}]$ex$::jsonb),
  ('92914028-1f3d-5b10-9383-a7c16ea1d813'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Percé jusques au fond du cœur","competence":"analyser-texte","situation":"En classe, vous comparez la manière dont Corneille et Racine peignent leurs héros. Voici le début des stances de Rodrigue, et une frise sur l’histoire de la pièce.","documents":[{"id":"stances","type":"texte","genre":"poeme","titre":"Début des stances","blocs":["Percé jusques au fond du cœur","D’une atteinte imprévue aussi bien que mortelle,","Misérable vengeur d’une juste querelle,","Et malheureux objet d’une injuste rigueur,","Je demeure immobile, et mon âme abattue","Cède au coup qui me tue."],"auteur":"Pierre Corneille","source":"Corneille, Le Cid (1637), acte I, scène 6 (début des stances)"},{"id":"frise","type":"frise","titre":"La pièce et son titre","debut":1630,"fin":1650,"pas":5,"periodes":[],"evenements":[{"id":"z1","date":1637,"nom":"Création du Cid"},{"id":"z2","date":1648,"nom":"Rebaptisé tragédie"}]}],"questions":[{"enonce":"Dans les quatre premiers vers, touche les **trois mots** qui disent que Rodrigue est frappé.","aide":"Cherche un participe, un nom et un adjectif qui évoquent un coup mortel.","type":"zone","document":"stances","multiple":true,"portee":[0,1,2,3]},{"enonce":"Touche les **deux adjectifs** qui s’opposent entre la querelle et la rigueur.","aide":"Cherche deux adjectifs dont l’un est le contraire de l’autre, aux vers 3 et 4.","type":"zone","document":"stances","multiple":true},{"enonce":"Que montrent les mots « Je demeure immobile » ?","aide":"Qu’est-ce qui empêche Rodrigue d’agir, au moment où il parle ?","type":"choix","options":[{"id":"a","texte":"Rodrigue s’est déjà décidé à venger son père"},{"id":"b","texte":"Rodrigue attend qu’on vienne lui donner un conseil"},{"id":"c","texte":"Rodrigue est paralysé par son dilemme"},{"id":"d","texte":"Rodrigue est tombé de fatigue après le duel"}],"multiple":false},{"enonce":"Combien d’années séparent la création du Cid du moment où Corneille le rebaptise « tragédie » ?","aide":"Soustrais 1637 de 1648.","type":"nombre","unite":"ans"},{"enonce":"Range chaque trait : héros de Corneille ou héros de Racine ?","aide":"Rodrigue choisit ; Titus (dans Bérénice) est dominé par une passion et par la loi de Rome.","type":"categories","categories":[{"id":"c0","texte":"Le héros de Corneille"},{"id":"c1","texte":"Le héros de Racine"}],"items":[{"id":"i0","texte":"Il se définit par sa volonté"},{"id":"i1","texte":"Il est écrasé par une passion qu’il subit"},{"id":"i2","texte":"Il choisit, quoi qu’il en coûte"},{"id":"i3","texte":"Il grandit par son choix"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m8","m13"]},"explication":"**Percé, atteinte, mortelle** : Rodrigue se dit blessé au cœur par l’affront fait à son père."},{"cle":{"type":"zone","ids":["m18","m25"]},"explication":"**juste** et **injuste** forment une antithèse : la querelle est juste, mais le sort qui l’accompagne est injuste."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le dilemme paralyse Rodrigue : quel que soit son choix, il **perd** quelque chose d’essentiel."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 ans","explication":"1648 − 1637 = **11 ans** : la tragi-comédie devient « tragédie » après la querelle du Cid."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Le héros cornélien se définit par sa **volonté** et grandit par son choix ; le héros racinien est **écrasé** par une passion qu’il subit."}]$ex$::jsonb),
  ('a5c44eab-38c6-5217-9e7b-4a722e681f01'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les nouvelles du club lecture","competence":"lire-tableau","situation":"Le club lecture du collège a recopié sur une fiche cinq récits courts que ses membres ont aimés. La documentaliste veut les ranger par registre et par auteur.","documents":[{"id":"etagere","type":"tableau","titre":"L’étagère du club lecture","colonnes":["Titre","Auteur","Registre"],"lignes":[["La Parure","Maupassant","Réaliste"],["Le Horla","Maupassant","Fantastique"],["La Vénus d’Ille","Mérimée","Fantastique"],["Micromégas","Voltaire","Conte philosophique"],["Boule de Suif","Maupassant","Réaliste"]],"enteteLignes":false}],"questions":[{"enonce":"Touche les **deux cases** qui désignent des nouvelles fantastiques.","aide":"Le fantastique, c’est l’irruption de l’inexplicable dans un cadre réaliste. Regarde la colonne « Registre ».","type":"zone","document":"etagere","multiple":true},{"enonce":"Touche l’auteur du XVIIIe siècle, qui a fait du récit bref un outil philosophique.","aide":"Cherche un nom qui ne soit ni Maupassant ni Mérimée, auteurs du XIXe siècle.","type":"zone","document":"etagere","multiple":false},{"enonce":"Combien de titres de Maupassant figurent sur l’étagère ?","aide":"Lis la colonne « Auteur » de haut en bas.","type":"nombre","unite":"titres"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2","r2c2"]},"explication":"**Le Horla** et **La Vénus d’Ille** sont des nouvelles fantastiques ; les autres sont réalistes ou philosophiques."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**Voltaire** écrit au XVIIIe siècle : ses contes philosophiques (Candide, Micromégas) font du récit bref un outil de réflexion."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 titres","explication":"Maupassant a écrit **La Parure, Le Horla et Boule de Suif** : 3 titres, du réalisme au fantastique."}]$ex$::jsonb),
  ('a5c44eab-38c6-5217-9e7b-4a722e681f01'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La fleur sur le pas de la porte","competence":"analyser-texte","situation":"Voici une très courte nouvelle écrite pour l’exercice. Sa chute est préparée : relis-la en cherchant les indices que le narrateur a semés.","documents":[{"id":"fleur","type":"texte","genre":"recit","titre":"La fleur du matin","blocs":["Chaque matin d’avril, Léo trouvait sur le pas de sa porte une marguerite fraîchement cueillie.","Il soupçonna la voisine du dessus, puis le facteur, puis la boulangère. Aucun ne savait rien. Les tiges étaient coupées de travers, comme avec des ciseaux d’écolier.","Un matin, il se leva avant l’aube et guetta derrière le rideau. Dans la terre humide du jardin, il remarqua des traces de pas minuscules.","À six heures, la porte du fond s’entrouvrit. Une petite fille en chemise de nuit déposa la fleur sur le seuil et s’enfuit en riant : c’était sa petite sœur Lili, âgée de cinq ans."],"source":"Nouvelle écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui, à la relecture, annonçaient déjà la chute.","aide":"Cherche deux mots qui évoquent un enfant, dans les paragraphes 2 et 3.","type":"zone","document":"fleur","multiple":true},{"enonce":"Quel type de chute cette nouvelle propose-t-elle ?","aide":"Qui apporte les fleurs ? Quand le lecteur l’apprend-il ?","type":"choix","options":[{"id":"a","texte":"Elle laisse l’histoire en suspens, sans jamais répondre à la question"},{"id":"b","texte":"Elle révèle une information cachée : l’identité de celle qui apporte les fleurs"},{"id":"c","texte":"Elle n’a pas de chute, car le texte se termine sur une description"},{"id":"d","texte":"Elle retourne la morale attendue : le méchant devient le héros du récit"}],"multiple":false},{"enonce":"Touche le prénom de celle qui dépose les fleurs.","aide":"C’est dans le dernier paragraphe, juste après « sa petite sœur ».","type":"zone","document":"fleur","multiple":true},{"enonce":"Complète ce que dit le cours sur une bonne chute.","aide":"Une chute qui sort de nulle part n’est pas une chute, c’est une invraisemblance.","type":"trous","segments":["Une bonne chute est ",0," : à la relecture, les ",1," étaient là."],"banque":["indices","préparée","inventée","hasards"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m43","m69"]},"explication":"**écolier** et **minuscules** étaient des indices : à la relecture, on comprend que le visiteur est un enfant."},{"cle":{"type":"choix","ids":["b"]},"explication":"La chute **révèle une information cachée** : la visiteuse est la petite sœur de Léo, comme dans La Parure la vérité sur le collier est révélée à la fin."},{"cle":{"type":"zone","ids":["m102"]},"explication":"C’est **Lili**, la petite sœur de cinq ans de Léo, qui apportait les fleurs."},{"cle":{"type":"trous","trous":[["preparee"],["indices"]]},"affichage":"préparée · indices","explication":"Une bonne chute est **préparée** : à la relecture, les **indices** étaient là."}]$ex$::jsonb),
  ('a5c44eab-38c6-5217-9e7b-4a722e681f01'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le chêne qui parle, la soupe qui fume","competence":"analyser-document","situation":"Deux élèves ont écrit chacun l’ouverture d’un récit : l’un fantastique, l’autre merveilleux. Leur professeur leur demande de justifier le registre choisi et de juger la chute d’un troisième texte.","documents":[{"id":"a","type":"texte","genre":"recit","titre":"Extrait A","blocs":["Madame Lefort habitait un appartement banal au troisième étage, près de la gare. Ce soir-là, en rentrant, elle trouva la table mise pour deux, alors qu’elle vivait seule.","La soupe fumait encore. Elle appela ; personne ne répondit. Dans le miroir de l’entrée, elle crut voir une silhouette s’asseoir."],"source":"Texte écrit pour l’exercice"},{"id":"b","type":"texte","genre":"recit","titre":"Extrait B","blocs":["Il était une fois, dans un royaume où les chênes parlaient, une princesse qui se promenait chaque matin sous leurs branches.","Quand le plus vieux chêne lui dit bonjour, elle répondit poliment, comme tout le monde, et lui demanda des nouvelles de ses glands."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque détail des deux extraits dans son registre.","aide":"Réaliste : le cadre ordinaire. Fantastique : l’inexplicable qui inquiète. Merveilleux : le surnaturel admis sans étonnement.","type":"categories","categories":[{"id":"c0","texte":"Fantastique"},{"id":"c1","texte":"Merveilleux"},{"id":"c2","texte":"Réaliste"}],"items":[{"id":"i0","texte":"Un appartement banal au troisième étage près de la gare"},{"id":"i1","texte":"Dans le miroir, une silhouette que personne d’autre ne voit"},{"id":"i2","texte":"La soupe fume alors que personne n’a cuisiné"},{"id":"i3","texte":"La princesse répond poliment au chêne, comme tout le monde"},{"id":"i4","texte":"Madame Lefort rentre le soir chez elle"},{"id":"i5","texte":"Un chêne salue la princesse et personne ne s’en étonne"}]},{"enonce":"Touche le mot qui prouve que quelqu’un vient de préparer le repas : c’est ce qui rend la scène inexplicable.","aide":"Que fait une soupe tout juste servie ?","type":"zone","document":"a","multiple":true},{"enonce":"Pourquoi l’extrait A est-il fantastique et non merveilleux ?","aide":"Compare avec l’extrait B : qui s’étonne, et qui ne s’étonne pas ?","type":"choix","options":[{"id":"a","texte":"Le texte est écrit au passé simple, comme tous les contes de fées"},{"id":"b","texte":"Un fait inexplicable surgit dans un cadre réaliste et inquiète l’héroïne"},{"id":"c","texte":"Le surnaturel y est accepté sans étonnement par tous les personnages"},{"id":"d","texte":"L’histoire se passe dans un royaume où les arbres savent parler"}],"multiple":false},{"enonce":"Un élève termine sa nouvelle par « Elle s’éveilla : ce n’était qu’un rêve. » Pourquoi est-ce une mauvaise chute ?","aide":"Une bonne chute est préparée par des indices.","type":"choix","options":[{"id":"a","texte":"Elle est trop courte pour qu’un lecteur puisse la comprendre"},{"id":"b","texte":"Elle laisse le lecteur sans aucune réponse à ses questions"},{"id":"c","texte":"Elle ne s’appuie sur aucun indice préparé : elle sort de nulle part"},{"id":"d","texte":"Elle révèle une information qui avait déjà été donnée au début"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c0","i3":"c1","i4":"c2","i5":"c1"}},"explication":"Le **réaliste** pose le cadre, le **fantastique** fait surgir l’inexplicable, le **merveilleux** admet le surnaturel sans étonnement."},{"cle":{"type":"zone","ids":["m31"]},"explication":"La soupe **fumait** : elle vient d’être servie, alors que personne n’est là. L’inexplicable fait irruption dans un cadre réaliste."},{"cle":{"type":"choix","ids":["b"]},"explication":"Dans le **fantastique**, l’inexplicable fait irruption dans le quotidien et provoque le trouble ; dans le **merveilleux**, le surnaturel est admis."},{"cle":{"type":"choix","ids":["c"]},"explication":"Une bonne chute est **préparée** ; « ce n’était qu’un rêve » sort de nulle part, c’est une invraisemblance et non une vraie chute."}]$ex$::jsonb),
  ('47687896-757b-5f82-9a14-52626788c308'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Gervaise, blanchisseuse à Paris","competence":"analyser-document","situation":"Pour son exposé, Axel présente L’Assommoir de Zola. Il a préparé une affiche avec les personnages principaux, une frise du cycle des Rougon-Macquart et une liste de l’intrigue à remettre en ordre.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"L’Assommoir","sousTitre":"Roman d’Émile Zola — 1877","emoji":"📖","teinte":"brun","lignes":[{"texte":"Gervaise Macquart","valeur":"Blanchisseuse, boiteuse","id":"z1"},{"texte":"Coupeau","valeur":"Ouvrier, son mari","id":"z2"},{"texte":"Nana","valeur":"Leur fille","id":"z3"}],"pied":"Septième roman des Rougon-Macquart"},{"id":"frise","type":"frise","titre":"Le cycle des Rougon-Macquart","debut":1870,"fin":1895,"pas":5,"periodes":[{"id":"z4","debut":1871,"fin":1893,"nom":"Les Rougon-Macquart","teinte":"brun"}],"evenements":[{"id":"z5","date":1877,"nom":"L’Assommoir"}]}],"questions":[{"enonce":"Touche l’héroïne de L’Assommoir.","aide":"C’est la blanchisseuse dont le roman raconte la vie et la déchéance.","type":"zone","document":"affiche","multiple":false},{"enonce":"Sur la frise, touche la date de publication de L’Assommoir.","aide":"Cherche l’événement placé à l’intérieur du cycle des Rougon-Macquart.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années après le début du cycle paraît L’Assommoir ?","aide":"Le cycle commence en 1871 : soustrais.","type":"nombre","unite":"ans"},{"enonce":"Remets l’intrigue de L’Assommoir dans l’ordre.","aide":"La chute de Coupeau est le point de bascule : avant, le couple réussit ; après, tout se défait.","type":"ordre","items":[{"id":"a","texte":"Ils ouvrent une blanchisserie"},{"id":"b","texte":"Elle épouse Coupeau"},{"id":"c","texte":"Gervaise sombre dans la misère"},{"id":"d","texte":"Gervaise arrive à Paris"},{"id":"e","texte":"Coupeau se met à boire"},{"id":"f","texte":"Coupeau tombe d’un toit"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Gervaise Macquart**, blanchisseuse et boiteuse, est l’héroïne : Zola montre comment le milieu défait une femme courageuse."},{"cle":{"type":"zone","ids":["z5"]},"explication":"L’Assommoir paraît en **1877**, au milieu du cycle des Rougon-Macquart (1871 à 1893)."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 ans","explication":"1877 − 1871 = **6 ans** : L’Assommoir est le septième roman d’un cycle de vingt romans."},{"cle":{"type":"ordre","ids":["d","b","a","f","e","c"]},"explication":"Après l’**accident de Coupeau**, l’alcool, les dettes et la faim entraînent la déchéance de Gervaise."}]$ex$::jsonb),
  ('47687896-757b-5f82-9a14-52626788c308'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Chez le père Colombe","competence":"analyser-texte","situation":"Voici une description écrite pour l’exercice, à la manière de Zola, d’un débit d’alcool de quartier populaire : on y entre en riant. Le texte est complété par une phrase qui résume la méthode de Zola.","documents":[{"id":"debit","type":"texte","genre":"recit","titre":"Le débit de boissons","blocs":["Au coin de la rue, la boutique du père Colombe luisait de tous ses cuivres. Dans la salle, un grand alambic ronflait sans repos et laissait couler goutte à goutte une eau-de-vie claire.","Les ouvriers entraient en riant, le verre à la main ; ils en sortaient en titubant, l’œil vitreux, la voix pâteuse."],"source":"Texte écrit pour l’exercice, à la manière de Zola"},{"id":"methode","type":"texte","genre":"source","titre":"La méthode du romancier","blocs":["Selon Zola, le romancier doit être à la fois observateur et expérimentateur."],"source":"D’après Zola, Le Roman expérimental (paraphrase, sans citation)"}],"questions":[{"enonce":"Touche les **deux mots** qui désignent la machine et l’alcool qui en coule.","aide":"Cherche un grand appareil de cuivre, puis ce qu’il fabrique.","type":"zone","document":"debit","multiple":true},{"enonce":"Touche le mot qui décrit la démarche des ouvriers à la sortie.","aide":"Cherche un participe présent qui dit qu’ils marchent mal.","type":"zone","document":"debit","multiple":true},{"enonce":"Quel effet produit le contraste entre l’entrée (« en riant ») et la sortie (« en titubant ») ?","aide":"Compare l’état des ouvriers avant et après le passage chez le père Colombe.","type":"choix","options":[{"id":"a","texte":"Il montre que le père Colombe est un cabaretier généreux"},{"id":"b","texte":"Il montre que les ouvriers sont heureux de leur journée"},{"id":"c","texte":"Il montre que l’alcool détruit ceux qui le boivent"},{"id":"d","texte":"Il montre que les ouvriers changent de métier le soir"}],"multiple":false},{"enonce":"Touche les **deux mots** qui disent la méthode scientifique que Zola attend du romancier.","aide":"Cherche deux noms qui se terminent par -teur, dans la phrase.","type":"zone","document":"methode","multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20","m31"]},"explication":"**alambic** et **eau-de-vie** : c’est le champ lexical de l’alcool, qui donne son nom au roman."},{"cle":{"type":"zone","ids":["m47"]},"explication":"**titubant** montre l’effet de l’alcool sur le corps des ouvriers : le milieu les atteint dans leur chair."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le contraste montre le **pouvoir destructeur de l’alcool** : le mot « assommoir » dit ce qui assomme."},{"cle":{"type":"zone","ids":["m9","m11"]},"explication":"Le romancier naturaliste est **observateur** (il regarde et se documente) et **expérimentateur** (il étudie l’effet du milieu et de l’hérédité)."}]$ex$::jsonb),
  ('47687896-757b-5f82-9a14-52626788c308'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Gervaise défaite, Zola accusé","competence":"analyser-document","situation":"En 1877, L’Assommoir fait scandale. Voici un passage écrit pour l’exercice à la manière de Zola, puis une lettre imaginaire d’un lecteur indigné. À toi de voir ce que Zola montre vraiment.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"La boutique de Gervaise","blocs":["Le lundi, Gervaise ne repassait plus. La boutique, jadis si claire, sentait le renfermé et le vin.","Coupeau, assis sur une caisse, un verre à la main, ne parlait plus de retourner sur les toits. Les créanciers frappaient à la porte, et Gervaise, qui avait tant ri autrefois, comptait ses sous en silence."],"source":"Texte écrit pour l’exercice, à la manière de Zola"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un lecteur indigné","blocs":["Monsieur,","J’ai lu L’Assommoir avec stupeur. M. Zola met dans la bouche de ses ouvriers l’argot du faubourg ; passe encore. Mais il l’emploie jusque dans la narration, comme si lui-même parlait ainsi.","Il se complaît dans la misère."],"source":"Lettre imaginée pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui disent l’abandon de la boutique et la pression de l’argent.","aide":"Cherche une odeur de lieu mal tenu, puis ceux qui viennent réclamer de l’argent.","type":"zone","document":"recit","multiple":true},{"enonce":"Dans la lettre, touche le mot qui désigne l’endroit du livre où l’argot a le plus choqué.","aide":"Le lecteur accepte l’argot dans les dialogues, mais pas ailleurs.","type":"zone","document":"lettre","multiple":true},{"enonce":"Selon le passage de Zola, pourquoi Gervaise tombe-t-elle ?","aide":"Zola ne condamne pas Gervaise : il étudie l’effet du milieu.","type":"choix","options":[{"id":"a","texte":"Elle perd tout son argent en jouant aux cartes avec ses voisins"},{"id":"b","texte":"Elle est paresseuse et mérite le malheur qui la frappe peu à peu"},{"id":"c","texte":"Elle abandonne sa boutique pour suivre un autre homme qu’elle aime"},{"id":"d","texte":"Le milieu (l’accident, l’alcool, les dettes) défait une femme courageuse"}],"multiple":false},{"enonce":"Range chaque trait : réalisme ou naturalisme ?","aide":"Le naturalisme applique la méthode scientifique ; le réalisme peint simplement le réel.","type":"categories","categories":[{"id":"c0","texte":"Réalisme"},{"id":"c1","texte":"Naturalisme"}],"items":[{"id":"i0","texte":"Zola et les Rougon-Macquart"},{"id":"i1","texte":"Balzac, Flaubert, Maupassant"},{"id":"i2","texte":"Étudier l’effet de l’hérédité et du milieu"},{"id":"i3","texte":"Appliquer au roman la méthode scientifique"},{"id":"i4","texte":"Peindre le réel tel qu’il est, sans idéaliser"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m36"]},"explication":"**renfermé** et **créanciers** montrent la déchéance : la boutique se dégrade et les dettes s’accumulent."},{"cle":{"type":"zone","ids":["m30"]},"explication":"C’est la **narration** : Zola fait entrer la langue du peuple jusque dans le récit, et pas seulement dans les dialogues."},{"cle":{"type":"choix","ids":["d"]},"explication":"Zola ne condamne pas Gervaise : il montre **comment le milieu défait une femme courageuse**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Le **réalisme** peint le réel tel qu’il est ; le **naturalisme** de Zola y ajoute la **méthode scientifique** et l’étude de l’hérédité et du milieu."}]$ex$::jsonb),
  ('5f0dd17a-731e-58c2-b628-990bc5b014c7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le résumé de Lina","competence":"analyser-texte","situation":"Lina présente *La Parure* à sa classe. Elle a rédigé un court résumé du début de la nouvelle : aide-la à en relever les éléments clés.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Le début de la nouvelle","source":"Résumé écrit pour l’exercice, d’après Maupassant, *La Parure* (1884)","blocs":["Mathilde Loisel est jolie, mais elle a épousé un petit employé de ministère et elle souffre de sa condition modeste. Un soir, son mari rapporte une invitation à un grand bal.","Pour ne pas paraître pauvre, elle emprunte à son amie Madame Forestier une rivière de diamants. Au bal, elle triomphe. Mais en rentrant, elle s’aperçoit qu’elle a perdu le bijou."]}],"questions":[{"enonce":"Touche les **deux mots** qui nomment le bijou emprunté (le nom du bijou, puis ce dont il est fait).","aide":"Le bijou est cité dans le second paragraphe.","type":"zone","document":"resume","multiple":true},{"enonce":"Touche le verbe qui dit ce que Mathilde ressent devant sa vie modeste.","aide":"Cherche dans le premier paragraphe : quel verbe exprime une douleur ?","type":"zone","document":"resume","multiple":false},{"enonce":"Le résumé dit « elle » et « son mari ». Qu’est-ce que cela montre sur le narrateur de la nouvelle de Maupassant ?","aide":"Un narrateur qui dit « elle » ne parle pas de lui-même.","type":"choix","options":[{"id":"a","texte":"Il est Madame Forestier et raconte ce qu’elle a vu"},{"id":"b","texte":"Il est un personnage du bal qui dit « je » dans le récit"},{"id":"c","texte":"Il est Mathilde elle-même et raconte sa propre vie"},{"id":"d","texte":"Il est extérieur à l’histoire et parle à la troisième personne"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m44","m46"]},"explication":"Le bijou est une **rivière de diamants**."},{"cle":{"type":"zone","ids":["m15"]},"explication":"Le verbe **souffre** montre dès le début l’insatisfaction de Mathilde."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le narrateur est **externe** : il raconte à la troisième personne, sans être un personnage de l’histoire."}]$ex$::jsonb),
  ('5f0dd17a-731e-58c2-b628-990bc5b014c7'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Dix ans pour payer la parure","competence":"analyser-document","situation":"Pour son exposé, Lina veut montrer comment Maupassant traite le temps. Elle a réuni un bilan des comptes du couple et le passage sur les années de remboursement.","documents":[{"id":"bilan","type":"fiche","modele":"etiquette","entete":"Le bilan des Loisel","sousTitre":"Pour remplacer la parure perdue","emoji":"💎","teinte":"violet","lignes":[{"texte":"Prix de la parure de remplacement","valeur":"36 000 francs"},{"texte":"Somme dont le couple dispose","valeur":"18 000 francs","id":"z1"}],"pied":"Bilan imaginé pour l’exercice, d’après *La Parure*"},{"id":"annees","type":"texte","genre":"recit","titre":"Les années de dette","source":"Texte écrit pour l’exercice, à la manière de Maupassant","blocs":["Mathilde apprit les gros travaux de la maison. Elle lava la vaisselle, usa ses ongles roses sur les casseroles, marchanda chez l’épicier. Et ainsi, mois après mois, pendant dix ans.","Quand tout fut payé, elle avait vieilli."]}],"questions":[{"enonce":"D’après le bilan, quelle somme le couple doit-il encore emprunter pour acheter la parure de remplacement ?","aide":"Prix de la parure moins la somme dont ils disposent.","type":"nombre","unite":"francs"},{"enonce":"Dans le texte, touche les **trois mots** qui donnent la durée du remboursement.","aide":"Cherche à la fin de la première phrase la plus longue.","type":"zone","document":"annees","multiple":true},{"enonce":"Dix années tiennent ici en quelques lignes. Quel procédé le narrateur emploie-t-il ?","aide":"Le temps du récit est bien plus court que le temps de l’histoire.","type":"choix","options":[{"id":"a","texte":"La chute : il révèle un secret à la dernière ligne du texte"},{"id":"b","texte":"Le portrait : il décrit longuement l’aspect physique du héros"},{"id":"c","texte":"Le dialogue : il fait parler les personnages pendant dix ans"},{"id":"d","texte":"L’ellipse : il passe sous silence une longue période de temps"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":18000,"tolerance":0},"affichage":"18 000 francs","explication":"36 000 − 18 000 = **18 000 francs** à emprunter."},{"cle":{"type":"zone","ids":["m28","m29","m30"]},"explication":"La durée tient en trois mots : **pendant dix ans**."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est une **ellipse** : la nouvelle accélère là où un roman s’attarderait."}]$ex$::jsonb),
  ('5f0dd17a-731e-58c2-b628-990bc5b014c7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Du livre à l’écran","competence":"analyser-document","situation":"Le ciné-club du collège projette l’adaptation télévisée de *La Parure* par Claude Chabrol. Avant la séance, Samir compare la nouvelle et le téléfilm.","documents":[{"id":"chute","type":"texte","genre":"source","titre":"La révélation, dans la nouvelle","source":"Maupassant, *La Parure* (1884) — dernières lignes de dialogue","blocs":["« Oh ! ma pauvre Mathilde ! Mais la mienne était fausse. Elle valait au plus cinq cents francs !… »"]},{"id":"compare","type":"tableau","titre":"Nouvelle et adaptation","colonnes":["","La nouvelle (1884)","Le téléfilm de Chabrol (2007)"],"enteteLignes":true,"lignes":[["Le support","Un texte écrit","Un téléfilm réalisé pour la télévision, dans la collection *Chez Maupassant*"],["Les dix années","Un paragraphe","Une durée réelle à montrer à l’écran"],["Qui raconte ?","Un narrateur qui rapporte sans commenter","Pas de discours du narrateur"]]}],"questions":[{"enonce":"Dans la réplique de Madame Forestier, touche l’adjectif qui retourne toute l’histoire.","aide":"Quel mot dit que la parure n’avait aucune valeur réelle ?","type":"zone","document":"chute","multiple":false},{"enonce":"Dans le tableau, touche la case qui dit ce que le téléfilm perd du côté du récit : la voix du narrateur.","aide":"Cherche la ligne « Qui raconte ? », colonne du téléfilm.","type":"zone","document":"compare","multiple":false},{"enonce":"Range ces éléments : l’écran les ajoute-t-il, ou les perd-il par rapport à la nouvelle ?","aide":"La caméra montre des choses concrètes ; le texte peut condenser et commenter.","type":"categories","categories":[{"id":"c0","texte":"Ce que la caméra ajoute"},{"id":"c1","texte":"Ce qu’elle perd"}],"items":[{"id":"i0","texte":"La mesquinerie des logements"},{"id":"i1","texte":"Les décors et la lumière du bal"},{"id":"i2","texte":"Les dix ans résumés en un paragraphe"},{"id":"i3","texte":"Le corps, le costume et la durée réelle"},{"id":"i4","texte":"Le discours du narrateur"}]},{"enonce":"Remets dans l’ordre les étapes de la nouvelle.","aide":"Commence par l’emprunt et termine par la chute.","type":"ordre","items":[{"id":"a","texte":"Mathilde emprunte une rivière de diamants"},{"id":"b","texte":"La révélation : la parure était fausse"},{"id":"c","texte":"Elle triomphe au bal"},{"id":"d","texte":"Elle perd la parure"},{"id":"e","texte":"Dix ans à rembourser"},{"id":"f","texte":"Le couple la remplace pour 36 000 francs"}]},{"enonce":"Que frappe-t-il Mathilde chez Maupassant : la fatalité ou le hasard ?","aide":"Une faute minuscule, une punition de dix ans : la peine est-elle proportionnée ?","type":"choix","options":[{"id":"a","texte":"Le hasard, qui n’a pas de justice à rendre"},{"id":"b","texte":"La fatalité, qui punit chaque faute selon sa gravité"},{"id":"c","texte":"Un complot monté par Madame Forestier contre elle"},{"id":"d","texte":"La justice, qui rend à chacun ce qu’il mérite ici"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"L’adjectif **fausse** est la chute : la parure perdue ne valait presque rien."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Le téléfilm perd **le discours du narrateur** : la caméra montre, elle ne commente pas."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"L’écran **ajoute** décors, lumière, corps, costumes, logements et durée réelle ; il **perd** le discours du narrateur et l’ellipse des dix ans."},{"cle":{"type":"ordre","ids":["a","c","d","f","e","b"]},"explication":"Emprunt, bal, perte, remplacement, dix ans de dette, puis **la révélation** finale."},{"cle":{"type":"choix","ids":["a"]},"explication":"Chez Maupassant, c’est **le hasard** qui frappe, et il n’a pas de justice à rendre : la punition est disproportionnée."}]$ex$::jsonb),
  ('b02b1c1e-c59d-57e1-89d8-f06af97b87f2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Fantastique, merveilleux ou science-fiction ?","competence":"analyser-document","situation":"La bibliothécaire du collège prépare trois étiquettes de genre pour ses rayons. Elle a un tableau du cours et trois résumés de livres à ranger.","documents":[{"id":"genres","type":"tableau","titre":"Le statut du surnaturel","colonnes":["Le genre","Le surnaturel…"],"enteteLignes":true,"lignes":[["Fantastique","fait irruption dans un cadre réaliste ; on ne sait jamais s’il faut y croire"],["Merveilleux","va de soi, comme dans le conte"],["Science-fiction","est expliqué par la science"]]}],"questions":[{"enonce":"Dans le tableau, touche la case qui dit que le surnaturel est expliqué par la science.","aide":"Cherche la ligne « Science-fiction », deuxième colonne.","type":"zone","document":"genres","multiple":false},{"enonce":"Range chacun de ces résumés dans le bon genre.","aide":"Pose-toi trois questions : est-ce naturel ? est-ce expliqué ? doute-t-on ?","type":"categories","categories":[{"id":"c0","texte":"Fantastique"},{"id":"c1","texte":"Merveilleux"},{"id":"c2","texte":"Science-fiction"}],"items":[{"id":"i0","texte":"Un vaisseau va plus vite que la lumière grâce à un moteur expliqué en détail"},{"id":"i1","texte":"Dans un appartement, un portrait semble cligner des yeux : fatigue ou fantôme ?"},{"id":"i2","texte":"Dans une forêt, un loup parle et une fée accorde trois vœux, sans surprise"}]},{"enonce":"Quel mot résume la marque du récit fantastique ?","aide":"C’est ce que ressent le narrateur devant le portrait.","type":"choix","options":[{"id":"a","texte":"La magie"},{"id":"b","texte":"La technologie"},{"id":"c","texte":"La moralité"},{"id":"d","texte":"L’hésitation"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Dans la science-fiction, le surnaturel **est expliqué par la science**."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1"}},"explication":"Le loup qui parle va de soi (**merveilleux**) ; le moteur est expliqué (**science-fiction**) ; le portrait laisse le doute (**fantastique**)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le fantastique repose sur **l’hésitation** : surnaturel, folie, rêve ou hallucination ?"}]$ex$::jsonb),
  ('b02b1c1e-c59d-57e1-89d8-f06af97b87f2'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Arrivée devant une demeure inquiétante","competence":"analyser-texte","situation":"Pour le concours d’écriture de la classe, Naël a imité l’art de Poe : un voyageur arrive de nuit devant une vieille demeure. Repère comment il entretient le doute.","documents":[{"id":"arrivee","type":"texte","genre":"recit","titre":"Le soir de mon arrivée","source":"Texte écrit pour l’exercice, à la manière d’Edgar Allan Poe","blocs":["J’arrivai à la nuit tombante devant la demeure de mon ami. La façade était lézardée et il me sembla qu’elle respirait, comme si la pierre était vivante.","La tempête grondait sur l’étang noir. Peut-être n’était-ce que la fatigue du voyage ; pourtant je crus entendre un soupir dans le mur."]}],"questions":[{"enonce":"Touche les **expressions** qui laissent le doute ouvert (« il me sembla », « comme si », « peut-être »).","aide":"Ce sont les modalisateurs : des mots qui disent « je n’en suis pas sûr ».","type":"zone","document":"arrivee","multiple":true},{"enonce":"Relie chaque procédé du fantastique à son rôle.","aide":"Un procédé, un effet.","type":"association","gauche":[{"id":"g0","texte":"Le narrateur interne, témoin"},{"id":"g1","texte":"Le cadre (maison isolée, nuit, tempête)"},{"id":"g2","texte":"La gradation"},{"id":"g3","texte":"Le modalisateur"}],"droite":[{"id":"d0","texte":"Il installe l’angoisse"},{"id":"d1","texte":"Elle fait monter la peur très progressivement"},{"id":"d2","texte":"On peut douter de lui"},{"id":"d3","texte":"Il garde le doute ouvert"}]},{"enonce":"Dans ce texte, le narrateur dit « j’arrivai ». Pourquoi cela renforce-t-il le doute ?","aide":"Peut-on vérifier ce que raconte un témoin unique ?","type":"choix","options":[{"id":"a","texte":"On ne voit que ce que lui voit : son témoignage peut être trompeur"},{"id":"b","texte":"Un narrateur à la première personne ne ment jamais au lecteur"},{"id":"c","texte":"Le récit à la première personne est toujours plus court"},{"id":"d","texte":"Cela prouve que le surnaturel existe réellement dans la maison"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m18","m19","m23","m24","m36"]},"explication":"Les modalisateurs sont **il me sembla, comme si, peut-être** : ils empêchent de trancher entre surnaturel et illusion."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"Le narrateur témoin est douteux, le cadre installe l’angoisse, la gradation la fait monter, le modalisateur garde le doute ouvert."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un narrateur **interne et témoin** n’offre que son point de vue : on peut douter de lui, donc de ce qu’il raconte."}]$ex$::jsonb),
  ('b02b1c1e-c59d-57e1-89d8-f06af97b87f2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La maison et la lignée","competence":"analyser-document","situation":"Le professeur demande d’expliquer le titre *La Chute de la maison Usher*. Un extrait écrit pour l’exercice et le déroulement de l’histoire vont t’y aider.","documents":[{"id":"fissure","type":"texte","genre":"recit","titre":"La maison et son maître","source":"Texte écrit pour l’exercice, à la manière d’Edgar Allan Poe","blocs":["Une lézarde fendait la façade du toit jusqu’à l’étang. Dans cette maison vivait le dernier héritier d’une famille éteinte, Roderick, que les sons, les lumières et les odeurs torturaient, et que sa sœur jumelle, Madeline, ne quittait plus."]},{"id":"recit","type":"chaine","disposition":"colonne","titre":"Le déroulement de la nouvelle","noeuds":[{"id":"z1","texte":"Le narrateur est appelé au chevet de Roderick"},{"id":"z2","texte":"Madeline meurt et on l’enferme dans un caveau"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Elle entraîne son frère dans la mort"},{"id":"z5","texte":"La maison se fend et sombre dans l’étang"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Touche le mot qui annonce déjà la chute de la maison.","aide":"Quel mot désigne une fente dans un mur ?","type":"zone","document":"fissure","multiple":false},{"enonce":"Quel épisode manque au milieu de la chaîne (case « ? ») ?","aide":"Elle revient pour entraîner son frère : que s’est-il passé dans le caveau ?","type":"choix","options":[{"id":"a","texte":"Le narrateur découvre que tout n’était qu’un rêve"},{"id":"b","texte":"Madeline reparaît : elle a été enterrée vivante"},{"id":"c","texte":"Roderick quitte la maison avec son ami d’enfance"},{"id":"d","texte":"Un médecin explique le mal de Roderick par la science"}],"multiple":false},{"enonce":"Quel lien unit Roderick et Madeline ?","aide":"Relis la fin du texte.","type":"choix","options":[{"id":"a","texte":"Ils sont mari et femme depuis longtemps"},{"id":"b","texte":"Ils sont deux amis d’enfance du narrateur"},{"id":"c","texte":"Ils sont frère et sœur jumeaux"},{"id":"d","texte":"Ils sont cousins éloignés de la même lignée"}],"multiple":false},{"enonce":"Complète pour expliquer le titre.","aide":"En anglais, un même mot, *house*, dit les deux.","type":"trous","segments":["La « chute de la maison Usher » désigne autant le ",0," que la ",1," des Usher."],"banque":["lignée","jardin","bâtiment","fortune"]},{"enonce":"Quelle « correspondance » la nouvelle établit-elle entre la maison et ses habitants ?","aide":"Pense à la lézarde et à la fin de Roderick.","type":"choix","options":[{"id":"a","texte":"Les habitants réparent la maison au fil des chapitres"},{"id":"b","texte":"La maison reste debout quand les habitants disparaissent"},{"id":"c","texte":"Les deux se fissurent puis s’effondrent au même instant"},{"id":"d","texte":"La maison protège les Usher contre tous les dangers"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"La **lézarde** annonce la chute : la maison se fissure avant de s’effondrer."},{"cle":{"type":"choix","ids":["b"]},"explication":"Madeline **reparaît, enterrée vivante**, puis entraîne son frère dans la mort."},{"cle":{"type":"choix","ids":["c"]},"explication":"Madeline est la sœur **jumelle** de Roderick : les deux derniers Usher meurent ensemble."},{"cle":{"type":"trous","trous":[["batiment"],["lignee"]]},"affichage":"bâtiment · lignée","explication":"Le titre est double : **le bâtiment** et **la lignée** s’effondrent ensemble."},{"cle":{"type":"choix","ids":["c"]},"explication":"La maison et les Usher **se fissurent ensemble et s’effondrent au même instant** : c’est la correspondance maison / habitant."}]$ex$::jsonb),
  ('c7aa5303-cee8-5f65-982a-d7988ca78342'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une brève pour le journal du collège","competence":"analyser-texte","situation":"Le journal du collège Jean-Moulin de Vallonne (collège imaginaire) publie une brève. Un bon article répond aux questions : qui, quoi, où, quand, pourquoi.","documents":[{"id":"breve","type":"texte","genre":"article","titre":"Un potager pour les 4e","source":"Article imaginé pour l’exercice","blocs":["Les élèves de 4e du collège Jean-Moulin de Vallonne ont inauguré mardi un potager dans la cour.","Le projet a été lancé pour apprendre à cultiver des légumes aux élèves de toutes les classes."]}],"questions":[{"enonce":"Touche le mot qui répond à la question « **où** ? ».","aide":"Cherche le nom de la ville dans le premier paragraphe.","type":"zone","document":"breve","multiple":false},{"enonce":"Touche le mot qui répond à la question « **quand** ? ».","aide":"C’est un jour de la semaine.","type":"zone","document":"breve","multiple":false},{"enonce":"Touche les mots qui répondent à « **pourquoi** ? » (le but du projet), de « pour » à « légumes ».","aide":"Le but suit le mot « pour » dans le second paragraphe.","type":"zone","document":"breve","multiple":true}]}$ex$::jsonb,
