  ('c7aa5303-cee8-5f65-982a-d7988ca78342'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Fait ou opinion dans le journal du collège ?","competence":"analyser-texte","situation":"Le journal du collège (imaginaire) mélange des informations et des avis. Zoé doit les distinguer avant de les classer dans les bonnes rubriques.","documents":[{"id":"journal","type":"texte","genre":"article","titre":"Les paragraphes du numéro de novembre","source":"Texte écrit pour l’exercice","blocs":["La cantine a servi 480 repas lundi, contre 450 la semaine précédente.","C’est scandaleux : les frites étaient beaucoup trop grasses.","Le conseil de classe de la 4e B se réunira jeudi à 17 h.","À mon avis, la nouvelle cour est bien plus belle que l’ancienne.","Le CDI est ouvert tous les midis de 12 h à 13 h.","Il faudrait absolument supprimer les devoirs du week-end."]}],"questions":[{"enonce":"Range chaque paragraphe du numéro (numérotés dans la marge) : est-ce un fait ou une opinion ?","aide":"Un fait se vérifie (chiffre, date, horaire). Une opinion exprime un jugement.","type":"categories","categories":[{"id":"c0","texte":"Un fait"},{"id":"c1","texte":"Une opinion"}],"items":[{"id":"i0","texte":"Paragraphe 3"},{"id":"i1","texte":"Paragraphe 6"},{"id":"i2","texte":"Paragraphe 5"},{"id":"i3","texte":"Paragraphe 4"},{"id":"i4","texte":"Paragraphe 2"},{"id":"i5","texte":"Paragraphe 1"}]},{"enonce":"Dans le paragraphe 2, touche les mots qui trahissent un jugement (trois mots).","aide":"Cherche un adjectif très fort et une intensité.","type":"zone","document":"journal","multiple":true},{"enonce":"Relie chaque situation au genre journalistique qui lui correspond.","aide":"Pense à la longueur, au terrain, à la forme questions-réponses.","type":"association","gauche":[{"id":"g0","texte":"Deux lignes sur le résultat d’un match"},{"id":"g1","texte":"Une journaliste passe trois jours dans une usine et raconte ce qu’elle voit"},{"id":"g2","texte":"Des questions posées au maire, avec ses réponses"},{"id":"g3","texte":"Six mois de recherches et de sources croisées"}],"droite":[{"id":"d0","texte":"Une interview"},{"id":"d1","texte":"Une enquête"},{"id":"d2","texte":"Une brève"},{"id":"d3","texte":"Un reportage"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Les paragraphes **1, 3 et 5** donnent des faits vérifiables ; les paragraphes **2, 4 et 6** expriment un avis."},{"cle":{"type":"zone","ids":["m14","m18","m19"]},"explication":"Les mots **scandaleux, beaucoup, trop** expriment un jugement : le paragraphe donne un avis."},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"Brève : l’essentiel en peu de lignes ; reportage : sur place ; interview : questions-réponses ; enquête : recherche longue avec recoupement."}]$ex$::jsonb),
  ('c7aa5303-cee8-5f65-982a-d7988ca78342'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La photo de l’inondation qui circule","competence":"analyser-document","situation":"Inès a reçu une photo d’inondation et veut la partager. Léo lui demande de vérifier d’abord. Voici leur échange et le résultat de ses vérifications.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Regarde, la rivière a tout inondé ce matin !! Partage vite !"},{"qui":"Léo","texte":"Tu as la source ? C’est signé ?"},{"qui":"Inès","texte":"Non, mais ça circule partout…"}]},{"id":"verifs","type":"tableau","titre":"Les vérifications d’Inès","colonnes":["Ce qu’on vérifie","Ce qu’Inès a trouvé"],"enteteLignes":true,"lignes":[["La source","Aucune : le message ne cite personne"],["La date","La photo date de six ans (recherche d’image inversée)"],["Le recoupement","Aucun média n’en parle"],["L’auteur","Un compte anonyme"]]}],"questions":[{"enonce":"Dans le tableau, touche la case qui prouve que la photo ne montre pas l’événement d’aujourd’hui.","aide":"Quelle vérification porte sur le moment où l’image a été prise ?","type":"zone","document":"verifs","multiple":false},{"enonce":"Inès relaie cette fausse nouvelle sans chercher à tromper. De quoi s’agit-il ?","aide":"Inès a-t-elle fabriqué l’information, ou seulement relayé ?","type":"choix","options":[{"id":"a","texte":"D’un reportage : le récit d’un journaliste venu sur place"},{"id":"b","texte":"D’une rumeur : une information non vérifiée, relayée de bonne foi"},{"id":"c","texte":"D’une infox : une fausse information fabriquée pour tromper"},{"id":"d","texte":"D’un éditorial : un texte d’opinion écrit par un journaliste"}],"multiple":false},{"enonce":"Relie chaque vérification à ce qu’elle cherche.","aide":"Reprends les lignes du tableau d’Inès.","type":"association","gauche":[{"id":"g0","texte":"La source"},{"id":"g1","texte":"La date"},{"id":"g2","texte":"Le recoupement"},{"id":"g3","texte":"L’auteur"}],"droite":[{"id":"d0","texte":"D’autres médias indépendants la donnent-ils ?"},{"id":"d1","texte":"L’image est-elle ancienne ?"},{"id":"d2","texte":"Qui signe, et est-il identifiable ?"},{"id":"d3","texte":"D’où vient l’information ?"}]},{"enonce":"Complète la règle d’Inès.","aide":"On la fait circuler à nouveau ; son message n’est plus le même.","type":"trous","segments":["Une image ancienne ",0," en circulation change de ",1,"."],"banque":["couleur","remise","prix","sens"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La **date** : la photo a six ans, elle a été remise en circulation."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est **une rumeur** : une information non vérifiée, relayée de bonne foi. L’infox, elle, est fabriquée pour tromper."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Source, date, recoupement et auteur : chaque contrôle pose **sa** question."},{"cle":{"type":"trous","trous":[["remise"],["sens"]]},"affichage":"remise · sens","explication":"Une image ancienne **remise** en circulation change de **sens**."}]$ex$::jsonb),
  ('e104a714-229a-5083-b718-e27552811460'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une affiche pour un pays imaginaire","competence":"analyser-document","situation":"Au CDI, on étudie une affiche de propagande inventée pour l’exercice : la Norvalia n’existe pas. Décris-la avec précision avant d’en tirer le message.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"NORVALIA ÉTERNELLE","sousTitre":"Un seul peuple, un seul Guide","emoji":"📢","teinte":"corail","lignes":[{"texte":"Le Guide","valeur":"vu d’en bas, au premier plan, le bras tendu","id":"z1"},{"texte":"La foule","valeur":"minuscule, en arrière-plan, qui l’acclame","id":"z2"},{"texte":"Les étrangers","valeur":"dessinés en ombres noires derrière des barbelés","id":"z3"},{"texte":"Le slogan","valeur":"« Eux nous volent, lui seul nous sauve ! »","id":"z4"}],"pied":"Affiche imaginée pour l’exercice — pays fictif"}],"questions":[{"enonce":"Touche la ligne qui décrit le **culte du chef** : un personnage grandi par le cadrage.","aide":"Cherche le personnage vu d’en bas : c’est une contre-plongée.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche la ligne qui montre l’**ennemi désigné** par l’affiche.","aide":"Qui est dessiné comme une menace, derrière des barbelés ?","type":"zone","document":"affiche","multiple":false},{"enonce":"Quel est le but de cette affiche ?","aide":"Informer, vendre ou faire adhérer ?","type":"choix","options":[{"id":"a","texte":"Vendre un produit en vantant ses qualités à l’acheteur"},{"id":"b","texte":"Faire adhérer le public à une idée politique, sans l’informer"},{"id":"c","texte":"Distraire le public avec une histoire drôle et sans enjeu"},{"id":"d","texte":"Informer le public avec des chiffres et plusieurs points de vue"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le Guide, **vu d’en bas** au premier plan, est grandi : c’est le culte du chef."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Les **étrangers** en ombres noires sont l’ennemi : le « eux » opposé au « nous »."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est de la **propagande** : elle vise à faire adhérer à une idée politique, en s’adressant aux émotions."}]$ex$::jsonb),
  ('e104a714-229a-5083-b718-e27552811460'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le tract du Comité","competence":"analyser-texte","situation":"Un tract imaginé pour l’exercice circule en Norvalia, pays fictif. Repère ses procédés, puis distingue propagande, publicité et information.","documents":[{"id":"tract","type":"texte","genre":"source","titre":"Tract du Comité de salut","source":"Tract imaginé pour l’exercice — pays fictif","blocs":["Des millions de gens le savent déjà : les étrangers nous ruinent.","La solution tient en un mot : obéir.","Un seul chef. Un seul chef. Un seul chef !"]}],"questions":[{"enonce":"Touche les mots qui forment un **argument d’autorité** (« tout le monde le sait »).","aide":"Cherche une foule invoquée pour prouver quelque chose.","type":"zone","document":"tract","multiple":true},{"enonce":"Range chaque phrase du tract selon le procédé de propagande qu’elle emploie.","aide":"Un procédé par phrase : martèlement, « eux » contre « nous », foule invoquée, formule toute faite.","type":"categories","categories":[{"id":"c0","texte":"Répétition"},{"id":"c1","texte":"Désignation d’un ennemi"},{"id":"c2","texte":"Argument d’autorité"},{"id":"c3","texte":"Simplification"}],"items":[{"id":"i0","texte":"La solution tient en un mot : obéir"},{"id":"i1","texte":"Des millions de gens le savent déjà"},{"id":"i2","texte":"Un seul chef. Un seul chef. Un seul chef !"},{"id":"i3","texte":"Les étrangers nous ruinent"}]},{"enonce":"Relie chaque document au type de discours auquel il appartient.","aide":"Vendre un produit, faire savoir, faire adhérer à une idée.","type":"association","gauche":[{"id":"g0","texte":"Une affiche vantant une marque de chocolat"},{"id":"g1","texte":"Un article donnant des chiffres sourcés et deux points de vue"},{"id":"g2","texte":"Une affiche qui désigne un ennemi pour rallier à un parti"}],"droite":[{"id":"d0","texte":"L’information"},{"id":"d1","texte":"La publicité"},{"id":"d2","texte":"La propagande"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1","m2","m3"]},"explication":"**Des millions de gens** : l’argument d’autorité fait croire que le nombre prouve la vérité."},{"cle":{"type":"categories","items":{"i0":"c3","i1":"c2","i2":"c0","i3":"c1"}},"explication":"Répétition du slogan, ennemi désigné, argument d’autorité, et **simplification** d’un problème complexe en un seul mot."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"La **publicité** vend un produit, l’**information** fait savoir avec du contradictoire, la **propagande** fait adhérer à une idée politique."}]$ex$::jsonb),
  ('e104a714-229a-5083-b718-e27552811460'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Qui parle, à qui, pour quoi faire ?","competence":"analyser-document","situation":"Pour l’exposé de la classe, Emma analyse une affiche électorale imaginée, d’un pays fictif, avec la grille d’analyse du cours.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Protégeons nos enfants","sousTitre":"Votez Parti du Renouveau","emoji":"👨‍👩‍👧","teinte":"violet","lignes":[{"texte":"Au premier plan","valeur":"une famille souriante devant un champ","id":"z1"},{"texte":"À l’arrière-plan","valeur":"des silhouettes sombres qui franchissent la frontière","id":"z2"},{"texte":"Commanditaire","valeur":"le Parti du Renouveau","id":"z3"},{"texte":"Contexte","valeur":"publiée trois semaines avant les élections","id":"z4"}],"pied":"Affiche imaginée pour l’exercice — pays fictif"},{"id":"grille","type":"tableau","titre":"La grille d’analyse du cours","colonnes":["La question","Ce qu’elle cherche"],"enteteLignes":true,"lignes":[["Nature","Affiche, discours, film, tract…"],["Auteur et commanditaire","Qui parle, et pour le compte de qui ?"],["Date et contexte","Que se passe-t-il à ce moment-là ?"],["Message implicite","Ce que le document fait croire sans le dire"]]}],"questions":[{"enonce":"Touche la ligne qui répond à la question « **pour le compte de qui** parle l’affiche ? ».","aide":"Cherche le nom de l’organisation qui a fait imprimer l’affiche.","type":"zone","document":"affiche","multiple":false},{"enonce":"Remets dans l’ordre les étapes de l’analyse d’un document de propagande.","aide":"On part de ce qu’est le document, et on finit par ce qu’il fait croire sans le dire.","type":"ordre","items":[{"id":"a","texte":"Date et contexte"},{"id":"b","texte":"Message implicite"},{"id":"c","texte":"Nature"},{"id":"d","texte":"Auteur et commanditaire"},{"id":"e","texte":"Destinataire"},{"id":"f","texte":"Message explicite"}]},{"enonce":"Quel est le message **implicite** de cette affiche ?","aide":"Relie l’arrière-plan sombre et le slogan « Protégeons nos enfants ».","type":"choix","options":[{"id":"a","texte":"Les étrangers seraient un danger pour les enfants"},{"id":"b","texte":"Le Parti du Renouveau veut construire de nouvelles écoles"},{"id":"c","texte":"Les familles ont droit à des vacances à la campagne"},{"id":"d","texte":"Les champs de ce pays sont les plus beaux du monde"}],"multiple":false},{"enonce":"Une image peut tromper sans être truquée. Parmi ces éléments, lesquels peuvent la faire mentir ?","aide":"Retiens la phrase du cours : une image ne ment jamais toute seule.","type":"choix","options":[{"id":"a","texte":"Sa légende"},{"id":"b","texte":"Le nombre de pixels de la photo"},{"id":"c","texte":"Son cadrage"},{"id":"d","texte":"Son contexte de publication"}],"multiple":true}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **commanditaire** est le Parti du Renouveau : il faut toujours l’identifier en premier."},{"cle":{"type":"ordre","ids":["c","d","a","e","f","b"]},"explication":"Nature, auteur et commanditaire, date et contexte, destinataire, message **explicite**, puis message **implicite**."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’affiche ne le dit pas, mais le contraste famille souriante / **silhouettes sombres** le laisse croire : c’est l’implicite."},{"cle":{"type":"choix","ids":["a","c","d"]},"explication":"Le **cadrage**, la **légende** et le **contexte** lui font dire ce qu’elle ne montre pas ; le nombre de pixels n’y change rien."}]$ex$::jsonb),
