   $ex${"titre":"Le journalisme sur deux siècles","competence":"se-reperer-temps","situation":"Pour l’exposé « Le journalisme à l’écran et dans les livres », Maël a placé quatre œuvres sur une frise. Aide-le à les situer et à les reconnaître.","documents":[{"id":"frise","type":"frise","titre":"Quatre œuvres sur le journalisme","debut":1800,"fin":2020,"pas":20,"evenements":[{"id":"z1","date":1837,"nom":"Illusions perdues"},{"id":"z2","date":1885,"nom":"Bel-Ami"},{"id":"z3","date":1976,"nom":"Les Hommes du président"},{"id":"z4","date":2015,"nom":"Spotlight"}]}],"questions":[{"enonce":"Touche le roman de Maupassant sur la frise.","aide":"Maupassant l’a publié en 1885.","type":"zone","document":"frise","multiple":false},{"enonce":"Relie chaque œuvre à ce qu’elle met en scène.","aide":"Un titre, un héros ou un sujet.","type":"association","gauche":[{"id":"g0","texte":"*Illusions perdues*"},{"id":"g1","texte":"*Bel-Ami*"},{"id":"g2","texte":"*Les Hommes du président*"},{"id":"g3","texte":"*Spotlight*"}],"droite":[{"id":"d0","texte":"Deux journalistes du *Washington Post* et le Watergate"},{"id":"d1","texte":"Une enquête menée pendant des mois avant publication"},{"id":"d2","texte":"Lucien de Rubempré, un provincial qui monte à Paris"},{"id":"d3","texte":"Georges Duroy, qui gravit les échelons sans talent"}]},{"enonce":"Combien d’années séparent la publication de *Bel-Ami* de la date du film *Spotlight* ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
