  ('b270ad70-ec61-5760-b00d-1f57aa02685f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un article qui se vend","competence":"analyser-texte","situation":"Pour comprendre ce que Balzac reproche à la presse, Camille lit une scène imaginée pour l’exercice, dans l’esprit d’*Illusions perdues* : un jeune provincial découvre un journal parisien.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Dans un journal parisien, vers 1840","source":"Scène imaginée pour l’exercice, dans l’esprit d’*Illusions perdues*","blocs":[{"didascalie":"Un jeune provincial vient d’arriver dans les bureaux du journal."},{"personnage":"Le rédacteur en chef","replique":"Un directeur de théâtre nous offre dix places et un dîner si nous éreintons la pièce de son rival."},{"personnage":"Le provincial","replique":"Mais je n’ai pas vu cette pièce !"},{"personnage":"Le rédacteur en chef","replique":"Qu’importe ! On n’a pas besoin de l’avoir vue pour en écrire trois colonnes. Ici, mon garçon, l’article se vend."}]}],"questions":[{"enonce":"Touche ce que le directeur de théâtre offre en échange d’un article.","aide":"Cherche la première réplique du rédacteur en chef.","type":"zone","document":"scene","multiple":true},{"enonce":"Touche les mots qui montrent qu’on peut juger une pièce sans l’avoir vue.","aide":"Cherche la dernière réplique, après « Qu’importe ! ».","type":"zone","document":"scene","multiple":true},{"enonce":"Que dénonce cette scène, comme Balzac et Maupassant ?","aide":"Le rédacteur en chef n’est pas seul : tout le monde y trouve son compte.","type":"choix","options":[{"id":"a","texte":"Un provincial trop naïf pour comprendre le métier à Paris"},{"id":"b","texte":"Un journaliste isolé qui trompe son directeur par vanité"},{"id":"c","texte":"Un théâtre qui refuse d’inviter les journalistes à ses soirées"},{"id":"d","texte":"Un système qui produit le mensonge, au-delà d’un seul menteur"}],"multiple":false},{"enonce":"Relie chaque œuvre à ce qu’elle montre du journalisme.","aide":"Deux œuvres du XIXe siècle, puis deux du XXe.","type":"association","gauche":[{"id":"g0","texte":"*Illusions perdues* (Balzac)"},{"id":"g1","texte":"*Bel-Ami* (Maupassant)"},{"id":"g2","texte":"Albert Londres"},{"id":"g3","texte":"*Les Hommes du président*"}],"droite":[{"id":"d0","texte":"Le Watergate, jusqu’à la démission d’un président"},{"id":"d1","texte":"Il invente le grand reportage"},{"id":"d2","texte":"L’article se vend"},{"id":"d3","texte":"Le journal sert à spéculer et à manœuvrer en politique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m18","m19","m20","m21"]},"explication":"Il offre **dix places et un dîner** : l’article est acheté."},{"cle":{"type":"zone","ids":["m40","m41","m42","m43","m44","m45","m46","m47","m48"]},"explication":"**On n’a pas besoin de l’avoir vue** : le jugement s’écrit sans avoir vu le spectacle."},{"cle":{"type":"choix","ids":["d"]},"explication":"Chez Balzac et Maupassant, ce n’est pas un menteur isolé : c’est **le système** qui produit le mensonge."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"XIXe : la presse comme machine (article vendu, journal outil de spéculation) ; XXe : le journalisme comme contre-pouvoir."}]$ex$::jsonb),
  ('b270ad70-ec61-5760-b00d-1f57aa02685f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Porter la plume dans la plaie","competence":"analyser-document","situation":"En classe, on compare les deux visages du journalisme : une presse qui se vend au XIXe siècle, un contre-pouvoir au XXe. Une phrase d’Albert Londres éclaire la seconde idée.","documents":[{"id":"londres","type":"texte","genre":"source","titre":"Une définition du métier","source":"Albert Londres, journaliste, inventeur du grand reportage","blocs":["« Notre métier n’est pas de faire plaisir, non plus de faire du tort, il est de porter la plume dans la plaie. »"]},{"id":"tab","type":"tableau","titre":"Quatre œuvres","colonnes":["L’œuvre","L’époque","Ce qu’elle montre"],"enteteLignes":true,"lignes":[["*Illusions perdues*","1837-1843","Un journaliste se perd dans une presse où l’article se vend"],["*Bel-Ami*","1885","Un journal instrument de spéculation politique"],["*Les Hommes du président*","1976","Deux journalistes du *Washington Post* et le Watergate"],["*Spotlight*","2015","Une enquête au long cours, des mois de vérification"]]}],"questions":[{"enonce":"Touche les **deux noms** qui forment l’image : l’outil du journaliste et l’endroit où il l’enfonce.","aide":"Une blessure, et ce qu’on écrit avec.","type":"zone","document":"londres","multiple":true},{"enonce":"Que veut dire Albert Londres par cette formule ?","aide":"Ni faire plaisir, ni faire du tort : alors quoi ?","type":"choix","options":[{"id":"a","texte":"Le journaliste doit éviter de blesser ses lecteurs"},{"id":"b","texte":"Le journaliste doit aller voir ce qui fait mal et le dire"},{"id":"c","texte":"Le journaliste doit écrire seulement des textes tristes"},{"id":"d","texte":"Le journaliste doit soigner les victimes qu’il rencontre"}],"multiple":false},{"enonce":"Dans le tableau, touche la case qui parle du *Washington Post*.","aide":"Cherche l’œuvre de 1976.","type":"zone","document":"tab","multiple":false},{"enonce":"Range chaque trait : presse « machine » du XIXe siècle, ou journalisme « contre-pouvoir » du XXe ?","aide":"Dans quel cas le journal sert-il ses intérêts ? Dans quel cas contrôle-t-il les puissants ?","type":"categories","categories":[{"id":"c0","texte":"La presse comme machine"},{"id":"c1","texte":"Le contre-pouvoir"}],"items":[{"id":"i0","texte":"Le journal sert à spéculer"},{"id":"i1","texte":"Une enquête qui mène à la démission d’un président"},{"id":"i2","texte":"On démolit une pièce qu’on n’a pas vue"},{"id":"i3","texte":"Des mois de vérification avant de publier"}]},{"enonce":"Que montre un film comme *Spotlight* que ne montre pas un simple article ?","aide":"Un article expose un fait. Et la fiction ?","type":"choix","options":[{"id":"a","texte":"Un avis personnel du réalisateur sur le lecteur du journal"},{"id":"b","texte":"Une nouvelle information plus vraie que celle de l’article"},{"id":"c","texte":"Une version plus courte de l’article, pour gagner du temps"},{"id":"d","texte":"Comment l’information a été obtenue et ce qu’elle a coûté"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19","m22"]},"explication":"Les noms **plume** et **plaie** forment l’image : le journaliste écrit là où ça fait mal."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le métier n’est ni de flatter ni de nuire : il est de **montrer et dire ce qui fait mal**, là où on préférerait se taire."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"La case de *Les Hommes du président* parle du *Washington Post* et du Watergate."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1"}},"explication":"Pièce démolie et journal-spéculation : la **presse machine** (XIXe). Vérification longue et Watergate : le **contre-pouvoir** (XXe)."},{"cle":{"type":"choix","ids":["d"]},"explication":"La fiction rend visibles **les conditions du travail** : délais, pressions, doute avant de publier."}]$ex$::jsonb),
  ('b0642ad8-fd82-5098-a691-f2de6b6d856e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’arrivée du provincial","competence":"analyser-texte","situation":"Mathis descend de la diligence à Paris. Un romancier du XIXe siècle décrirait la ville par ses yeux : repère les procédés de ce passage écrit pour l’exercice.","documents":[{"id":"arrivee","type":"texte","genre":"recit","titre":"Mathis découvre la ville","source":"Texte écrit pour l’exercice, dans l’esprit du roman du XIXe siècle","blocs":["En descendant de la diligence, Mathis découvre la ville. Elle gronde sous les roues des fiacres, elle avale la foule dans ses rues étroites.","Autour de lui, cris, sabots et cloches se mêlent sans répit : il se sent minuscule."]}],"questions":[{"enonce":"Touche les **deux verbes** qui donnent à la ville des attributs d’un être vivant (personnification).","aide":"Une ville ne gronde ni n’avale vraiment : cherche dans la première phrase.","type":"zone","document":"arrivee","multiple":true},{"enonce":"Touche les **trois mots** du champ lexical du bruit.","aide":"Cherche dans le second paragraphe.","type":"zone","document":"arrivee","multiple":true},{"enonce":"Pourquoi peut-on parler de focalisation interne dans ce passage ?","aide":"Qui perçoit la ville dans ce texte ?","type":"choix","options":[{"id":"a","texte":"Parce que la ville est décrite de loin, depuis un point élevé"},{"id":"b","texte":"Parce que Mathis raconte l’histoire à la première personne"},{"id":"c","texte":"Parce que le narrateur sait tout ce qui se passe dans la ville"},{"id":"d","texte":"Parce que la ville est montrée à travers ce que Mathis voit et ressent"}],"multiple":false}]}$ex$::jsonb,
