  ('b0642ad8-fd82-5098-a691-f2de6b6d856e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois romanciers, trois villes","competence":"analyser-texte","situation":"Le professeur a distribué trois extraits imaginés pour l’exercice, écrits à la manière de Balzac, de Zola et de Hugo. À toi de reconnaître la ville de chacun.","documents":[{"id":"extraits","type":"texte","genre":"recit","titre":"Trois extraits","source":"Textes écrits pour l’exercice, à la manière de Balzac, Zola et Hugo","blocs":["Paris s’étendait sous ses yeux comme un champ de bataille : il fallait y avancer, y frapper, y vaincre, sinon la ville vous dévorait.","Dans ces quelques rues, tout se tenait : le loyer, le bruit, la misère. Le quartier faisait les gens, et les gens ne pouvaient plus lui échapper.","Il s’enfonça dans les ruelles, descendit dans les égouts, se cacha derrière une barricade : la ville n’avait pas d’issue."]}],"questions":[{"enonce":"Relie chaque extrait (numéroté dans la marge) à la ville qu’il décrit.","aide":"Combat, quartier qui façonne les gens, ruelles et égouts.","type":"association","gauche":[{"id":"g0","texte":"Extrait 1"},{"id":"g1","texte":"Extrait 2"},{"id":"g2","texte":"Extrait 3"}],"droite":[{"id":"d0","texte":"Un milieu qui détermine (Zola)"},{"id":"d1","texte":"Un champ de bataille (Balzac)"},{"id":"d2","texte":"Un labyrinthe (Hugo)"}]},{"enonce":"Dans l’extrait 1, touche le verbe qui personnifie la ville.","aide":"Quelle action fait la ville à ceux qui ne vainquent pas ?","type":"zone","document":"extraits","multiple":false},{"enonce":"Remets dans l’ordre les causes qui rendent Paris méconnaissable au XIXe siècle.","aide":"Les gens arrivent, l’industrie s’installe, puis on reconstruit.","type":"ordre","items":[{"id":"a","texte":"Paris devient méconnaissable en trente ans"},{"id":"b","texte":"L’exode rural"},{"id":"c","texte":"Les grands travaux d’Haussmann"},{"id":"d","texte":"La révolution industrielle"}]},{"enonce":"Pourquoi *L’Assommoir* de Zola se joue-t-il dans quelques rues de la Goutte-d’Or ?","aide":"Pour Zola, la ville est un milieu qui détermine.","type":"choix","options":[{"id":"a","texte":"Parce que Zola ne connaissait pas d’autres quartiers de Paris"},{"id":"b","texte":"Parce que le quartier explique le destin des personnages"},{"id":"c","texte":"Parce que le roman raconte une enquête policière dans ces rues"},{"id":"d","texte":"Parce que la Goutte-d’Or est le plus beau quartier de la ville"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Extrait 1 : champ de bataille (Balzac) ; extrait 2 : milieu qui détermine (Zola) ; extrait 3 : labyrinthe (Hugo)."},{"cle":{"type":"zone","ids":["m23"]},"explication":"Le verbe **dévorait** donne à la ville une bouche : c’est une personnification."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"L’**exode rural**, la **révolution industrielle**, les **grands travaux d’Haussmann** : en trente ans, Paris est méconnaissable."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le quartier est **un milieu qui détermine** : il explique le destin de ceux qui y vivent."}]$ex$::jsonb),
