   $ex${"titre":"Un même quartier, deux regards","competence":"analyser-texte","situation":"Deux personnages décrivent le même quartier d’une grande ville. Le romancier choisit ce qu’il montre : compare leurs descriptions, écrites pour l’exercice.","documents":[{"id":"promeneur","type":"texte","genre":"recit","titre":"Le regard d’un promeneur aisé","source":"Texte écrit pour l’exercice","blocs":["Le quartier est charmant : des vitrines étincelantes, des fiacres élégants, des lampes allumées dès le soir."]},{"id":"blanchisseuse","type":"texte","genre":"recit","titre":"Le regard d’une blanchisseuse","source":"Texte écrit pour l’exercice","blocs":["Le quartier est une impasse : de la boue jusqu’aux chevilles, du bruit toute la nuit, de la fumée dans les rues."]}],"questions":[{"enonce":"Dans le second texte, touche les **deux noms** qui disent la saleté du quartier.","aide":"Ce qui salit les chaussures, ce qui noircit l’air.","type":"zone","document":"blanchisseuse","multiple":true},{"enonce":"Range chaque détail : montre-t-il une ville qui séduit ou une ville qui écrase ?","aide":"Relis les deux textes : l’un choisit la lumière, l’autre la boue.","type":"categories","categories":[{"id":"c0","texte":"Une ville qui séduit"},{"id":"c1","texte":"Une ville qui écrase"}],"items":[{"id":"i0","texte":"De la fumée dans les rues"},{"id":"i1","texte":"Des vitrines étincelantes"},{"id":"i2","texte":"De la boue jusqu’aux chevilles"},{"id":"i3","texte":"Des fiacres élégants"},{"id":"i4","texte":"Du bruit toute la nuit"}]},{"enonce":"Les deux textes décrivent le même quartier. Pourquoi sont-ils si différents ?","aide":"Décrire, c’est choisir : que garde-t-on, que laisse-t-on ?","type":"choix","options":[{"id":"a","texte":"Le romancier connaît mal le quartier qu’il décrit"},{"id":"b","texte":"L’un des deux textes ment, l’autre dit tout le vrai"},{"id":"c","texte":"Chacun choisit ce qu’il montre, selon son jugement"},{"id":"d","texte":"Le quartier a complètement changé entre les textes"}],"multiple":false},{"enonce":"Quel nom porte le procédé qui oppose un quartier riche et un quartier pauvre, souvent à quelques rues d’écart ?","aide":"Il oppose deux choses très différentes l’une à côté de l’autre.","type":"texte","placeholder":"Un seul mot"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m18"]},"explication":"Les noms **boue** et **fumée** disent la saleté : le champ lexical d’une ville qui écrase."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Vitrines et fiacres **séduisent** ; boue, bruit et fumée **écrasent**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Décrire une ville, c’est toujours porter **un jugement** : le choix de ce qu’on montre dit l’intention de celui qui décrit."},{"cle":{"type":"texte","acceptes":["contraste","le contraste"]},"affichage":"contraste","explication":"C’est **le contraste** : les deux regards opposent la ville des vitrines à celle de la boue."}]$ex$::jsonb),
  ('5b9ab20a-14af-58fa-a25c-bd2a53961130'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Il pleut sur la ville","competence":"analyser-texte","situation":"Pour le recueil de poèmes de la classe, Inès a recopié deux vers célèbres de Verlaine. Lis-les lentement : que ressent le poète, et quel rapport a-t-il avec la ville ?","documents":[{"id":"verlaine","type":"texte","genre":"poeme","titre":"Deux vers de Verlaine","auteur":"Paul Verlaine","source":"Paul Verlaine, *Romances sans paroles* (1874) — deux vers","blocs":["Il pleure dans mon cœur","Comme il pleut sur la ville"]}],"questions":[{"enonce":"Touche les **deux verbes** qui se ressemblent et relient la tristesse du poète à la pluie.","aide":"Un verbe par vers : les larmes, puis la pluie.","type":"zone","document":"verlaine","multiple":true},{"enonce":"Quelle ville Verlaine fait-il voir dans ces vers ?","aide":"Que dit la pluie sur l’état d’esprit du poète ?","type":"choix","options":[{"id":"a","texte":"Une ville moderne remplie d’affiches et de hangars"},{"id":"b","texte":"Une ville joyeuse, pleine de fêtes et de lumières"},{"id":"c","texte":"Une ville rêvée et démesurée"},{"id":"d","texte":"Une ville pluvieuse et mélancolique"}],"multiple":false},{"enonce":"Relie chaque poète à sa ville.","aide":"Un poète, une ville : relis les adjectifs.","type":"association","gauche":[{"id":"g0","texte":"Verlaine"},{"id":"g1","texte":"Rimbaud"},{"id":"g2","texte":"Apollinaire"},{"id":"g3","texte":"Baudelaire"}],"droite":[{"id":"d0","texte":"Un Paris parcouru par un flâneur"},{"id":"d1","texte":"Pluvieuse et mélancolique"},{"id":"d2","texte":"Rêvée et démesurée"},{"id":"d3","texte":"Un Paris moderne, sans ponctuation"}]}]}$ex$::jsonb,
