  ('5b9ab20a-14af-58fa-a25c-bd2a53961130'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Boue et or : le poème d’un flâneur","competence":"analyser-texte","situation":"Dans un atelier d’écriture, Léa a imité Baudelaire : elle veut transformer la laideur de la ville en poésie. Repère ses procédés.","documents":[{"id":"poeme","type":"texte","genre":"poeme","titre":"Ô ville","source":"Poème écrit pour l’exercice, à la manière de Baudelaire","blocs":["Ô ville, ton vacarme a la couleur du plomb,","Ton soleil noir se lève sur les toits ;","Je marche dans ta boue, et ton ombre m’apprend","À voir de l’or dans ce que nul ne regarde."]}],"questions":[{"enonce":"Touche l’**oxymore** du vers 2 : deux mots de sens contraires associés.","aide":"Un astre qui éclaire, mais qui est… sombre.","type":"zone","document":"poeme","multiple":true},{"enonce":"Dans le vers 1, touche les **deux mots** qui mêlent une sensation de l’oreille et une sensation de la vue (synesthésie).","aide":"Un bruit qui aurait une couleur.","type":"zone","document":"poeme","multiple":true},{"enonce":"Que fait ce poète de la boue et de la laideur de la ville ?","aide":"Pense à la phrase de Baudelaire : « Tu m’as donné ta boue et j’en ai fait de l’or. »","type":"choix","options":[{"id":"a","texte":"Il les efface pour décrire une ville imaginaire"},{"id":"b","texte":"Il les cache pour ne montrer que de belles choses"},{"id":"c","texte":"Il les condamne sans y trouver aucune beauté"},{"id":"d","texte":"Il les transfigure : il en fait de la beauté"}],"multiple":false},{"enonce":"Relie chaque procédé à ce qu’il permet.","aide":"Un procédé, un effet.","type":"association","gauche":[{"id":"g0","texte":"La personnification"},{"id":"g1","texte":"L’oxymore"},{"id":"g2","texte":"L’énumération"},{"id":"g3","texte":"La synesthésie"}],"droite":[{"id":"d0","texte":"Dire la beauté du laid"},{"id":"d1","texte":"Mêler bruits, odeurs et couleurs"},{"id":"d2","texte":"La ville devient un être"},{"id":"d3","texte":"Mimer le défilé du regard"}]}]}$ex$::jsonb,
