  ('5b9ab20a-14af-58fa-a25c-bd2a53961130'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un Paris sans ponctuation","competence":"analyser-texte","situation":"Pour l’exposé « La poésie entre dans la ville », Samir a relevé deux dates et écrit un poème à la manière d’Apollinaire. Retrouve ses repères et ses procédés.","documents":[{"id":"frise","type":"frise","titre":"Deux jalons de la poésie urbaine","debut":1850,"fin":1920,"pas":10,"evenements":[{"id":"z1","date":1857,"nom":"Les Fleurs du mal"},{"id":"z2","date":1913,"nom":"« Zone »"}]},{"id":"poeme","type":"texte","genre":"poeme","titre":"La nuit dans la ville","source":"Poème écrit pour l’exercice, à la manière d’Apollinaire","blocs":["j’ai marché toute la nuit dans la ville","les affiches criaient les enseignes clignotaient","un tramway un hangar une grue un cri","la tour sous la lune ressemblait à un bouquet de fer"]}],"questions":[{"enonce":"Sur la frise, touche le poème d’Apollinaire qui ouvre *Alcools* sur un Paris moderne.","aide":"Son titre tient en un mot, entre guillemets.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent *Les Fleurs du mal* de « Zone » ?","aide":"Lis les deux dates sur la frise, puis soustrais.","type":"nombre","unite":"ans"},{"enonce":"Dans le poème, touche les **quatre éléments** de l’énumération qui mime le défilé du regard.","aide":"Cherche le vers qui accumule des noms sans les relier.","type":"zone","document":"poeme","multiple":true},{"enonce":"Que montre l’absence de ponctuation dans ce poème, comme dans « Zone » ?","aide":"Sans pauses, on avance d’une traite, comme dans la ville.","type":"choix","options":[{"id":"a","texte":"Un flux continu, qui épouse le désordre de la ville"},{"id":"b","texte":"Une règle obligatoire pour tous les poèmes en vers"},{"id":"c","texte":"Un poème écrit en une seule fois, sans le relire"},{"id":"d","texte":"Un manque de soin de la part de l’auteur du poème"}],"multiple":false},{"enonce":"Quelles formes poétiques s’imposent pour dire ce désordre urbain ?","aide":"Il faut une forme souple, sans règles trop strictes.","type":"choix","options":[{"id":"a","texte":"Le haïku et la comptine rimée"},{"id":"b","texte":"Le sonnet et l’alexandrin régulier"},{"id":"c","texte":"La fable et l’épopée en vers"},{"id":"d","texte":"Le vers libre et le poème en prose"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"**« Zone »** (1913) ouvre *Alcools* sur un Paris moderne."},{"cle":{"type":"nombre","valeur":56,"tolerance":0},"affichage":"56 ans","explication":"1913 − 1857 = **56 ans**."},{"cle":{"type":"zone","ids":["m16","m18","m20","m22"]},"explication":"L’énumération **tramway, hangar, grue, cri** fait défiler la ville sous le regard du poète."},{"cle":{"type":"choix","ids":["a"]},"explication":"Sans ponctuation, le texte **file comme le regard** dans la ville : il épouse son désordre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **vers libre** et le **poème en prose** sont assez souples pour épouser le désordre urbain."}]$ex$::jsonb),
