  ('25408f17-a202-5e42-9aaa-740ad9343e15'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Atget, Doisneau et une planche de BD","competence":"analyser-document","situation":"Pour l’exposition du CDI, deux documents imaginés pour l’exercice : le cartel d’une salle de photographies et la description d’une planche de bande dessinée.","documents":[{"id":"cartel","type":"texte","genre":"source","titre":"Cartel d’exposition","source":"Cartel imaginé pour l’exercice, d’après des faits connus","blocs":["Eugène Atget photographie le vieux Paris avant sa disparition : rues vides, boutiques, cours. Son archive est devenue œuvre.","Robert Doisneau et Willy Ronis montrent le Paris populaire de l’après-guerre : enfants, bistrots, amoureux. Le célèbre baiser de l’Hôtel de Ville, de Doisneau, n’est pas un instantané : c’est une photographie mise en scène."]},{"id":"planche","type":"texte","genre":"source","titre":"Une planche de BD","source":"Planche imaginée pour l’exercice, décrite case par case","blocs":["Case 1 (grande, plan général) : une place de Paris en 1914, un mur couvert d’affiches. Cartouche : « Août. »","Case 2 (petite) : une femme ferme sa porte, une valise à la main. Bulle : « Je reviendrai. »","Case 3 (petite) : la même place, vide, sous la pluie. Cartouche : « Quatre ans plus tard. »"]}],"questions":[{"enonce":"Touche le nom du photographe qui a documenté le vieux Paris avant sa disparition.","aide":"Cherche le début du premier paragraphe.","type":"zone","document":"cartel","multiple":true},{"enonce":"Que dit le cartel du baiser de l’Hôtel de Ville ?","aide":"Relis la fin du second paragraphe : instantané ou pas ?","type":"choix","options":[{"id":"a","texte":"Une image retouchée pour une publicité de journal"},{"id":"b","texte":"Une image prise sur le vif, sans aucune préparation"},{"id":"c","texte":"Une image dessinée par un artiste, et non photographiée"},{"id":"d","texte":"Une image qui semble spontanée peut avoir été mise en scène"}],"multiple":false},{"enonce":"Touche le texte du **cartouche** de la case 3, celui qui fait avancer le temps.","aide":"Le cartouche est la voix du narrateur ; cherche dans la case 3.","type":"zone","document":"planche","multiple":true},{"enonce":"Entre la case 2 et la case 3, quatre ans passent. Qui comble ce temps non montré ?","aide":"Ce qu’on ne voit pas dans la BD, qui l’imagine ?","type":"choix","options":[{"id":"a","texte":"Le dessinateur, qui dessine toutes les années en détail"},{"id":"b","texte":"Le lecteur lui-même, grâce à l’ellipse entre les cases"},{"id":"c","texte":"La bulle de la femme, qui raconte ce qui s’est passé"},{"id":"d","texte":"Le titre de la planche, qui résume l’histoire entière"}],"multiple":false},{"enonce":"Relie chaque notion de BD à ce qu’elle désigne.","aide":"Sur la planche décrite, repère « bulle » et « cartouche ».","type":"association","gauche":[{"id":"g0","texte":"La case"},{"id":"g1","texte":"La planche"},{"id":"g2","texte":"La bulle"},{"id":"g3","texte":"Le cartouche"}],"droite":[{"id":"d0","texte":"La parole d’un personnage"},{"id":"d1","texte":"Le texte du narrateur"},{"id":"d2","texte":"La composition d’ensemble"},{"id":"d3","texte":"L’unité de lecture"}]}]}$ex$::jsonb,
