  ('2b7b7129-b680-5559-83f6-c675d1f5476b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le voyage d’un navire de Nantes","competence":"lire-carte","situation":"En 1770, un armateur de Nantes envoie un navire sur la route du commerce triangulaire. Sur la carte, trois étapes sont tracées : suis-les une à une.","documents":[{"id":"carte","type":"carte","titre":"Les trois étapes du navire","fond":"monde","cadrage":[-85,5,20,55],"source":"Carte simplifiée, écrite pour l’exercice.","lieux":[{"id":"z1","lieu":"nantes","symbole":"point","nom":"Nantes"},{"id":"z2","lieu":"dakar","symbole":"point","nom":"Côte du Sénégal"},{"id":"z3","lieu":"fort-de-france","symbole":"point","nom":"Antilles"}],"traits":[{"id":"z4","points":["nantes","dakar"],"style":"fleche","teinte":"violet","etiquette":"1"},{"id":"z5","points":["dakar","fort-de-france"],"style":"fleche","teinte":"corail","etiquette":"2"},{"id":"z6","points":["fort-de-france","nantes"],"style":"fleche","teinte":"ambre","etiquette":"3"}]}],"questions":[{"enonce":"Touche le trait qui représente la traversée des captifs vers l’Amérique.","aide":"Cette traversée part d’Afrique et arrive aux Antilles.","type":"zone","document":"carte","multiple":false},{"enonce":"Associe chaque étape à ce que le navire transporte.","aide":"Le navire repart toujours chargé : à l’aller, il apporte des marchandises ; au retour, il ramène les produits des plantations.","type":"association","gauche":[{"id":"g0","texte":"Étape 1 : Nantes → Afrique"},{"id":"g1","texte":"Étape 2 : Afrique → Antilles"},{"id":"g2","texte":"Étape 3 : Antilles → Nantes"}],"droite":[{"id":"d0","texte":"Des captifs"},{"id":"d1","texte":"Du sucre, du café, du coton"},{"id":"d2","texte":"Des armes, des tissus, de l’alcool"}]},{"enonce":"Comment appelle-t-on la traversée de l’Atlantique avec les captifs ? Écris les trois mots : « le … du … ».","aide":"Le mot du milieu veut dire que cette étape est la deuxième sur trois.","type":"texte","placeholder":"le … du …"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"C’est l’étape **2**, de l’Afrique vers les Antilles : la traversée de l’Atlantique, appelée le « passage du milieu »."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"À l’aller, des marchandises contre des captifs ; au milieu, des **captifs** ; au retour, les **produits des plantations**. Chaque étape rapporte de l’argent à l’armateur."},{"cle":{"type":"texte","acceptes":["passage du milieu","le passage du milieu"]},"affichage":"passage du milieu","explication":"On l’appelle le **passage du milieu** : c’est la deuxième étape, au milieu du triangle."}]$ex$::jsonb),
  ('2b7b7129-b680-5559-83f6-c675d1f5476b'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le registre du navire et la loi","competence":"analyser-document","situation":"Lina, archiviste à Nantes, ouvre le registre imaginaire d’un navire négrier. Elle le compare à un article du Code Noir, la loi royale de 1685.","documents":[{"id":"registre","type":"tableau","titre":"Registre d’un navire (imaginé)","source":"Chiffres écrits pour l’exercice, d’après la proportion donnée par le cours.","colonnes":["Ligne du registre","Nombre"],"lignes":[["Captifs embarqués en Afrique",300],["Captifs morts pendant la traversée (un sur six)","?"],["Marins de l’équipage",40]],"enteteLignes":true},{"id":"code","type":"texte","genre":"source","titre":"Le statut de l’esclave","auteur":"D’après l’article 44 du Code Noir (1685) — texte adapté pour l’exercice","blocs":["Les esclaves sont des meubles : ils entrent dans les biens de leur maître comme un objet. Il peut les vendre, les donner et les laisser en héritage à ses enfants."]}],"questions":[{"enonce":"Touche, dans le texte, le mot qui dit ce qu’est un esclave pour la loi.","aide":"Cherche le mot qui compare l’esclave à un objet que l’on possède.","type":"zone","document":"code","multiple":false},{"enonce":"Dans ce registre, un captif sur six meurt pendant la traversée. Combien de morts compte-t-on parmi les 300 captifs embarqués ?","aide":"Divise 300 par 6.","type":"nombre","unite":"morts"},{"enonce":"Que change le mot « meuble » pour la vie d’un esclave ?","aide":"Un meuble s’achète, se vend et se lègue.","type":"choix","options":[{"id":"a","texte":"Il peut choisir librement son maître."},{"id":"b","texte":"Il devient propriétaire de sa maison aux Antilles."},{"id":"c","texte":"Il est traité en droit comme une chose qu’on peut vendre."},{"id":"d","texte":"Il reçoit un salaire en échange de son travail."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"Le Code Noir classe l’esclave parmi les **meubles** : un bien que l’on possède, que l’on vend et que l’on transmet."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 morts","explication":"300 ÷ 6 = **50 morts** : ce sont les conditions de la traversée (entassement, maladies, révoltes réprimées) qui tuent."},{"cle":{"type":"choix","ids":["c"]},"explication":"Être un **bien meuble**, c’est être juridiquement une chose : on la possède, on la vend, on la transmet. L’esclave n’a aucun des droits d’une personne."}]$ex$::jsonb),
  ('2b7b7129-b680-5559-83f6-c675d1f5476b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un armateur de Nantes face aux Amis des Noirs","competence":"se-reperer-temps","situation":"Pierre, élève de 4e, prépare un exposé sur la traite. Il dispose d’une frise des dates clés et d’une lettre imaginée d’un armateur nantais qui réagit à une société nouvelle, fondée en 1788.","documents":[{"id":"frise","type":"frise","titre":"De la loi à l’abolition définitive","debut":1680,"fin":1860,"pas":20,"evenements":[{"id":"z1","date":1685,"nom":"Code Noir"},{"id":"z2","date":1788,"nom":"Amis des Noirs"},{"id":"z3","date":1794,"nom":"Première abolition"},{"id":"z4","date":1802,"nom":"Rétablissement"},{"id":"z5","date":1848,"nom":"Abolition définitive"}]},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un armateur nantais (1788)","auteur":"Lettre imaginaire, écrite pour l’exercice","blocs":["Nantes, 1788. Monsieur, on me dit qu’une société nouvelle, à Paris, veut en finir avec la traite.","Or chaque voyage de mon navire me rapporte : mes tissus et mes armes s’échangent contre des captifs, les captifs contre du sucre, le sucre contre de l’argent. Si l’on arrête un seul de ces échanges, ma fortune s’arrête avec lui."]}],"questions":[{"enonce":"Range ces quatre événements du plus ancien au plus récent.","aide":"Lis les dates sous chaque point de la frise.","type":"ordre","items":[{"id":"a","texte":"La première abolition de l’esclavage"},{"id":"b","texte":"La fondation de la Société des amis des Noirs"},{"id":"c","texte":"Le rétablissement de l’esclavage"},{"id":"d","texte":"Le Code Noir"}]},{"enonce":"Touche sur la frise l’événement qui annule l’abolition de 1794.","aide":"Cherche ce qui arrive après la première abolition et qui remet l’esclavage en place.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années passent entre le rétablissement de l’esclavage et son abolition définitive ?","aide":"Soustrais la date du rétablissement à celle de l’abolition définitive.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot de la lettre qui montre que l’armateur pense d’abord à l’argent.","aide":"Cherche le verbe qui dit ce que chaque voyage fait gagner à l’armateur.","type":"zone","document":"lettre","multiple":false},{"enonce":"Que révèle cette lettre sur les raisons qui font durer la traite ?","aide":"Relis la phrase où l’armateur compte ce que chaque échange lui apporte.","type":"choix","options":[{"id":"a","texte":"Les armateurs ignorent tout de la traite des captifs."},{"id":"b","texte":"Les ports atlantiques s’appauvrissent grâce à la traite."},{"id":"c","texte":"Le roi interdit déjà tout commerce avec l’Afrique."},{"id":"d","texte":"Chaque étape rapporte, donc les armateurs la défendent."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["d","b","a","c"]},"explication":"Code Noir (**1685**), Amis des Noirs (**1788**), première abolition (**1794**), rétablissement (**1802**) : la route vers l’abolition n’est pas une ligne droite."},{"cle":{"type":"zone","ids":["z4"]},"explication":"En **1802**, Bonaparte rétablit l’esclavage dans les colonies : c’est un retour en arrière, huit ans après 1794."},{"cle":{"type":"nombre","valeur":46,"tolerance":0},"affichage":"46 ans","explication":"1848 − 1802 = **46 ans**. Entre les deux, des révoltes, des débats et des mobilisations ont fini par l’emporter."},{"cle":{"type":"zone","ids":["m25"]},"explication":"L’armateur écrit que chaque voyage lui **rapporte** : pour lui, la traite est avant tout une affaire rentable à chaque étape."},{"cle":{"type":"choix","ids":["d"]},"explication":"La lettre montre la **raison économique** de la persistance de la traite : chaque étape rapporte, et ceux qui en vivent défendent le système. Face à eux, les Amis des Noirs font entendre une autre voix."}]$ex$::jsonb),
  ('6255e663-4edf-5792-a61b-5d5e190bdddd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’exposé d’Inès sur quatre grands livres","competence":"lire-tableau","situation":"Inès prépare un exposé sur les Lumières. Elle a rangé dans un tableau quatre livres célèbres du XVIIIe siècle avec leur date.","documents":[{"id":"livres","type":"tableau","titre":"Quatre livres des Lumières","source":"Dates de publication, d’après le cours.","colonnes":["Penseur","Livre","Année"],"lignes":[["Montesquieu","De l’esprit des lois","1748"],["Diderot et d’Alembert","L’Encyclopédie (28 volumes)","1751-1772"],["Rousseau","Du contrat social","1762"],["Voltaire","Traité sur la tolérance","1763"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’année de publication du livre le plus ancien.","aide":"Compare les années : la plus petite correspond au livre le plus ancien.","type":"zone","document":"livres","multiple":false},{"enonce":"Combien d’années passent entre la parution de *De l’esprit des lois* (1748) et celle du *Contrat social* ?","aide":"Lis l’année du *Contrat social* dans le tableau, puis soustrais 1748.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque penseur à son idée maîtresse.","aide":"Pense au titre de leur œuvre : *l’esprit des lois*, *le contrat social*, *tolérance*, *Encyclopédie*.","type":"association","gauche":[{"id":"g0","texte":"Montesquieu"},{"id":"g1","texte":"Rousseau"},{"id":"g2","texte":"Voltaire"},{"id":"g3","texte":"Diderot et d’Alembert"}],"droite":[{"id":"d0","texte":"La souveraineté du peuple"},{"id":"d1","texte":"Réunir tout le savoir"},{"id":"d2","texte":"La séparation des pouvoirs"},{"id":"d3","texte":"La tolérance religieuse"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Le plus ancien est *De l’esprit des lois* de Montesquieu, paru en **1748**."},{"cle":{"type":"nombre","valeur":14,"tolerance":0},"affichage":"14 ans","explication":"1762 − 1748 = **14 ans**."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"Montesquieu sépare les pouvoirs, Rousseau place la souveraineté dans le peuple, Voltaire défend la tolérance, Diderot et d’Alembert rassemblent le savoir dans l’**Encyclopédie**."}]$ex$::jsonb),
  ('6255e663-4edf-5792-a61b-5d5e190bdddd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois souverains qui réforment sans partager","competence":"analyser-document","situation":"À Berlin, à Saint-Pétersbourg et à Vienne, des souverains se disent inspirés par les Lumières. Léa compare leurs capitales sur une carte et lit un édit imaginé.","documents":[{"id":"carte","type":"carte","titre":"Trois capitales de souverains éclairés","fond":"europe","cadrage":[-5,40,45,65],"lieux":[{"id":"z1","lieu":"berlin","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lieu":"saint-petersbourg","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"vienne-autriche","symbole":"lettre","lettre":"C","teinte":"ambre"}],"legende":[{"teinte":"violet","symbole":"lettre","texte":"A : Berlin (Prusse), Frédéric II"},{"teinte":"corail","symbole":"lettre","texte":"B : Saint-Pétersbourg (Russie), Catherine II"},{"teinte":"ambre","symbole":"lettre","texte":"C : Vienne (Autriche), Joseph II"}]},{"id":"edit","type":"texte","genre":"source","titre":"Un édit imaginé","auteur":"Édit imaginaire, écrit pour l’exercice","blocs":["Nous voulons que chacun de nos sujets puisse prier selon sa conscience, et que des écoles soient ouvertes dans tous nos villages.","Mais aucune assemblée ne sera élue : Nous seul décidons des lois de notre royaume."]}],"questions":[{"enonce":"Touche la lettre qui désigne la capitale de la Russie de Catherine II.","aide":"Lis la légende : une seule lettre correspond à la Russie.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les mots de l’édit qui montrent que le souverain garde tout le pouvoir.","aide":"Cherche qui décide des lois, à la fin du texte.","type":"zone","document":"edit","multiple":true},{"enonce":"Classe chaque élément : est-ce une réforme éclairée ou une marque du pouvoir gardé ?","aide":"Relis l’édit : les deux premières idées sont données au peuple, les deux dernières sont refusées.","type":"categories","categories":[{"id":"c0","texte":"Une réforme au nom des Lumières"},{"id":"c1","texte":"Un pouvoir que le souverain garde"}],"items":[{"id":"i0","texte":"L’ouverture d’écoles dans les villages"},{"id":"i1","texte":"Lui seul décide des lois"},{"id":"i2","texte":"Aucune assemblée élue"},{"id":"i3","texte":"La liberté de prier selon sa conscience"}]},{"enonce":"Pourquoi appelle-t-on ces souverains des « despotes éclairés » ?","aide":"« Éclairé » renvoie aux Lumières, « despote » au pouvoir sans partage.","type":"choix","options":[{"id":"a","texte":"Ils refusent toute réforme par attachement à la tradition."},{"id":"b","texte":"Ils réforment mais gardent tout le pouvoir."},{"id":"c","texte":"Ils sont choisis par le peuple pour le gouverner."},{"id":"d","texte":"Ils partagent le pouvoir avec une assemblée élue."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La capitale de Catherine II est **Saint-Pétersbourg**, repérée par la lettre B, au nord-est de la carte."},{"cle":{"type":"zone","ids":["m28","m29"]},"explication":"« **Nous seul** décidons des lois » : le souverain réforme, mais ne partage rien. C’est le **despotisme éclairé**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"Tolérance et écoles sont des **réformes éclairées** ; l’absence d’assemblée et la décision seul sont les marques du **pouvoir gardé**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le **despotisme éclairé**, c’est réformer au nom du peuple, jamais avec lui : Frédéric II, Catherine II et Joseph II gardent tout le pouvoir."}]$ex$::jsonb),
  ('6255e663-4edf-5792-a61b-5d5e190bdddd'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Séparer les pouvoirs : deux royaumes imaginaires","competence":"analyser-texte","situation":"Deux phrases célèbres des Lumières servent à juger deux royaumes inventés, Valdor et Arnis. Lequel applique l’idée de Montesquieu ?","documents":[{"id":"phrases","type":"texte","genre":"source","titre":"Deux phrases célèbres","auteur":"Montesquieu, De l’esprit des lois, livre XI (1748) ; Rousseau, Du contrat social, livre I (1762)","blocs":["« Pour qu’on ne puisse abuser du pouvoir, il faut que, par la disposition des choses, le pouvoir arrête le pouvoir. »  (Montesquieu)","« L’homme est né libre, et partout il est dans les fers. »  (Rousseau)"]},{"id":"royaumes","type":"tableau","titre":"Deux royaumes imaginaires","source":"Tableau écrit pour l’exercice.","colonnes":["Pouvoir","Valdor","Arnis"],"lignes":[["Fait les lois","Le roi","Une assemblée élue"],["Applique les lois","Le roi","Le roi et ses ministres"],["Juge","Le roi","Des tribunaux indépendants"]],"enteteLignes":true}],"questions":[{"enonce":"Touche, dans la phrase de Montesquieu, le mot qui dit ce que chaque pouvoir doit faire à l’autre.","aide":"Cherche le verbe qui complète « le pouvoir … le pouvoir ».","type":"zone","document":"phrases","multiple":false},{"enonce":"Touche les trois cases qui montrent qu’à Valdor un seul homme concentre tous les pouvoirs.","aide":"Regarde la colonne de Valdor : qui fait, applique et juge ?","type":"zone","document":"royaumes","multiple":true},{"enonce":"Quel royaume applique l’idée de séparation des pouvoirs ?","aide":"Compare, ligne par ligne, qui détient chaque pouvoir dans chaque royaume.","type":"choix","options":[{"id":"a","texte":"Aucun des deux royaumes, car le roi y décide de tout"},{"id":"b","texte":"Arnis, où les pouvoirs sont confiés à des mains différentes"},{"id":"c","texte":"Les deux royaumes, car chacun a des lois et un roi"},{"id":"d","texte":"Valdor, où le roi tient tous les pouvoirs sans partage"}],"multiple":false},{"enonce":"Quel penseur a écrit « L’homme est né libre, et partout il est dans les fers » ?","aide":"Cette phrase ouvre le livre qui parle de la souveraineté du peuple.","type":"choix","options":[{"id":"a","texte":"Rousseau"},{"id":"b","texte":"Voltaire"},{"id":"c","texte":"Diderot"},{"id":"d","texte":"Montesquieu"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Pour Montesquieu, le pouvoir doit **arrêter** le pouvoir : aucun pouvoir ne doit être seul, sinon il abuse."},{"cle":{"type":"zone","ids":["r0c1","r1c1","r2c1"]},"explication":"À Valdor, **le roi** fait les lois, les applique et juge : exactement ce que Montesquieu veut empêcher."},{"cle":{"type":"choix","ids":["b"]},"explication":"À **Arnis**, l’assemblée fait les lois, le roi et ses ministres les appliquent, des tribunaux jugent : les pouvoirs sont séparés et se limitent."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est **Rousseau**, au début du *Contrat social* (1762) : l’autorité doit venir de ceux qui obéissent."}]$ex$::jsonb),
  ('49b51a1c-152a-5f93-9a94-69520a6b9e39'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui paie l’impôt dans la France de 1788 ?","competence":"lire-graphique","situation":"Nous sommes en 1788. Un secrétaire du roi veut savoir comment se répartissent les Français entre les trois ordres. Il lit ce diagramme en secteurs.","documents":[{"id":"ordres","type":"graphique","forme":"secteurs","titre":"Les trois ordres de la population","source":"Ordres de grandeur arrondis, d’après le cours.","categories":["Clergé","Noblesse","Tiers état"],"series":[{"nom":"Part de la population (%)","valeurs":[0.5,1.5,98],"teinte":"violet"}]}],"questions":[{"enonce":"Touche l’ordre qui rassemble presque toute la population.","aide":"Cherche le plus grand secteur du diagramme.","type":"zone","document":"ordres","multiple":false},{"enonce":"Quelle part de la population forment ensemble le clergé et la noblesse ? Réponds en pourcentage.","aide":"Additionne les deux petits secteurs : 0,5 et 1,5.","type":"nombre","unite":"%"},{"enonce":"Associe chaque ordre à sa situation devant l’impôt.","aide":"Deux ordres sont privilégiés ; l’autre est celui qui paie.","type":"association","gauche":[{"id":"g0","texte":"Clergé"},{"id":"g1","texte":"Noblesse"},{"id":"g2","texte":"Tiers état"}],"droite":[{"id":"d0","texte":"Privilégiée"},{"id":"d1","texte":"Il paie"},{"id":"d2","texte":"Privilégié : exempté de l’essentiel"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"Le **tiers état** représente environ 98 % des Français."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 %","explication":"0,5 + 1,5 = **2 %** : deux Français sur cent seulement appartiennent aux ordres privilégiés."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Clergé et noblesse sont **privilégiés** ; le tiers état, 98 % de la population, **paie** : c’est l’une des sources de la colère de 1789."}]$ex$::jsonb),
  ('49b51a1c-152a-5f93-9a94-69520a6b9e39'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le journal de Marie, été 1789","competence":"analyser-texte","situation":"Marie, une jeune Parisienne imaginaire, tient son journal à la fin de l’été 1789. Elle raconte, dans le désordre, les événements qui ont changé le royaume.","documents":[{"id":"journal","type":"texte","genre":"lettre","titre":"Journal de Marie, 26 août 1789","auteur":"Texte écrit pour l’exercice","blocs":["Aujourd’hui, 26 août, l’Assemblée a publié la Déclaration des droits de l’homme et du citoyen. Papa dit que c’est un grand jour.","Pourtant, l’hiver dernier, nous avions faim : la récolte avait été mauvaise et le pain était hors de prix.","Le 14 juillet, des Parisiens ont pris la Bastille, la prison du roi. Plus tôt, le 20 juin, les députés du tiers état avaient juré au Jeu de paume de ne pas se séparer avant d’avoir donné une constitution.","Et dans la nuit du 4 août, l’Assemblée a aboli les privilèges."]}],"questions":[{"enonce":"Touche le mot qui explique pourquoi le peuple est en colère avant 1789.","aide":"Cherche l’aliment de base devenu trop cher après la mauvaise récolte.","type":"zone","document":"journal","multiple":false},{"enonce":"Range ces quatre événements cités par Marie dans l’ordre où ils se sont produits.","aide":"Marie raconte dans le désordre : cherche les dates écrites dans le journal.","type":"ordre","items":[{"id":"a","texte":"Le serment du Jeu de paume"},{"id":"b","texte":"La Déclaration des droits de l’homme et du citoyen"},{"id":"c","texte":"L’abolition des privilèges"},{"id":"d","texte":"La prise de la Bastille"}]},{"enonce":"Combien de jours séparent la prise de la Bastille (14 juillet) de la Déclaration des droits (26 août) ?","aide":"Il reste 17 jours en juillet après le 14, puis il faut ajouter les 26 jours d’août.","type":"nombre","unite":"jours"},{"enonce":"Quel est l’effet de la nuit du 4 août ?","aide":"Relis la dernière phrase du journal.","type":"choix","options":[{"id":"a","texte":"Elle exécute le roi."},{"id":"b","texte":"Elle donne le droit de vote aux femmes."},{"id":"c","texte":"Elle abolit l’esclavage dans les colonies."},{"id":"d","texte":"Elle abolit les privilèges des ordres."}],"multiple":false}]}$ex$::jsonb,
