tique."}],"multiple":false},{"enonce":"Dans la monarchie constitutionnelle de 1791, qui peut voter avec le suffrage censitaire ?","aide":"Seuls les hommes qui paient un certain impôt votent.","type":"categories","categories":[{"id":"c0","texte":"Peut voter en 1791"},{"id":"c1","texte":"Ne peut pas voter en 1791"}],"items":[{"id":"i0","texte":"Une femme"},{"id":"i1","texte":"Un homme qui paie l’impôt exigé"},{"id":"i2","texte":"Un esclave des colonies"},{"id":"i3","texte":"Un homme trop pauvre pour l’impôt exigé"}]}]}$ex$::jsonb,
