r ?","aide":"Pense à la Convention qui gouverne en 1793-1794.","type":"choix","options":[{"id":"a","texte":"La Convention qui arrête sur soupçon libère les esclaves."},{"id":"b","texte":"Il n’a aucun lien avec les débats de la Révolution."},{"id":"c","texte":"Il rétablit l’esclavage dans toutes les colonies."},{"id":"d","texte":"Il est voté par un roi qui gouverne sans assemblée."}],"multiple":false}]}$ex$::jsonb,
