   $ex${"titre":"La journée de Louis, ouvrier à douze ans","competence":"analyser-document","situation":"Louis, 12 ans, travaille dans une filature en 1840. Son récit imaginaire et un tableau de salaires montrent comment la fabrique change le travail.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Une journée de Louis","auteur":"Récit imaginaire, écrit pour l’exercice","blocs":["La cloche sonne à 5 h et nous entrons dans la fabrique. Elle sonne de nouveau à 19 h : on sort. Entre les deux, une seule heure de pause pour manger.","Dans l’atelier de mon père, on travaillait à la tâche, quand on voulait. Ici, on travaille à l’heure, à côté des machines."]},{"id":"salaires","type":"tableau","titre":"Salaire par jour, en francs (imaginé)","source":"Chiffres imaginés, proches de ceux de l’époque.","colonnes":["Ouvrier","Salaire par jour"],"lignes":[["Un homme","2 F"],["Une femme","1 F"],["Un enfant","0,50 F"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui rythme la journée dans la fabrique.","aide":"Cherche l’objet qui sonne pour entrer et pour sortir.","type":"zone","document":"recit","multiple":false},{"enonce":"Combien d’heures Louis travaille-t-il par jour, une fois la pause retirée ?","aide":"Calcule d’abord de 5 h à 19 h, puis retire la pause.","type":"nombre","unite":"heures"},{"enonce":"Touche le salaire de Louis par jour.","aide":"Louis est un enfant.","type":"zone","document":"salaires","multiple":false},{"enonce":"Pourquoi les patrons emploient-ils beaucoup d’enfants ?","aide":"Compare les trois salaires du tableau.","type":"choix","options":[{"id":"a","texte":"La loi les oblige à les embaucher."},{"id":"b","texte":"Ils coûtent moins cher qu’un homme."},{"id":"c","texte":"Ils travaillent plus vite que les adultes."},{"id":"d","texte":"Ils sont mieux formés que les adultes."}],"multiple":false}]}$ex$::jsonb,
